# 추천인데 사용자 정보가 전혀 없을 때: 답변 대신 되묻기
# v9.29: 심사는 단일턴이라 되물어도 사용자가 답할 기회가 없다.
#   질문만 하고 끝내면 '요구사항 충족'에서 실점하므로,
#   한 답변 안에 '확인 질문 + 경우별 실질 안내'를 모두 담게 한다.
