def pension_limit(question):
    """v9.32: 세액공제 한도는 상품에 따라 다르다.
    연금저축에만 넣었으면 600만원, IRP(또는 퇴직연금)가 함께면 합산 900만원.
    실측 오류: '연금저축에 1,800만원' 질문에 한도 900을 적용해 148.5만원이라 답했다
    (정답은 600만 x 16.5% = 99만원)."""
    q = question.upper()
    has_irp = any(k in q for k in ("IRP", "개인형퇴직연금", "퇴직연금", "DC", "DB"))
    has_only_ysj = ("연금저축" in question) and not has_irp
    if has_only_ysj:
        return 600, "연금저축 단독"
    return 900, "연금저축+IRP 합산"


_ACC_PS = re.compile(r"연금저축[^\d\n]{0,12}?([\d,]+)\s*만\s*원")
_ACC_IRP = re.compile(r"(?:IRP|개인형\s*퇴직연금)[^\d\n]{0,12}?([\d,]+)\s*만\s*원")


def split_accounts(question, paid=None):
    """v13.7(D4/D5): 질문에서 연금저축·IRP 금액을 계좌별로 분리한다. (ps, irp) 또는 None.
    연금저축분은 600만원까지만 공제 대상이므로 '합계 하나'로는 한도를 맞출 수 없다(실측 D4 700+200→900,
    D5 800+100→900). 분리 금액의 합이 추출 납입액과 다르면(월납 환산 등) 신뢰하지 않고 None."""
    _ps = [float(x.replace(",", "")) for x in _ACC_PS.findall(question)]
    _ir = [float(x.replace(",", "")) for x in _ACC_IRP.findall(question)]
    if not _ps:
        return None
    ps = sum(_ps)
    irp = sum(_ir) if _ir else 0.0
    if paid is not None and abs((ps + irp) - paid) > 1:
        return None
    return ps, irp


def income_kind_of(question):
    """v13.7(F3): 세액공제율 경계는 총급여 5,500만원 = 종합소득금액 4,500만원.
    질문이 종합소득(사업소득자)만 말하면 4,500만원 경계를 써야 한다(실측 F3: 5,000만원에 16.5% 오적용)."""
    if re.search(r"종합\s*소득", question) and not re.search(r"총\s*급여|연봉|근로소득", question):
        return "종합소득"
    return "총급여"


_INC_KEY = re.compile(r"(종합\s*소득(?:\s*금액)?|총\s*급여(?:액)?|세전\s*연봉|연봉|연\s*소득|(?<!퇴직)급여)"
                      r"[은는이가의도]?\s*(?:[가-힣]{1,4}\s*)?"
                      r"((?:[\d,]+(?:\.\d+)?\s*(?:억|천|백|만)?\s*){1,4})\s*원?")
_KOR_TOK = re.compile(r"([\d,]+(?:\.\d+)?)\s*(억|천|백|만)?")


def parse_man(text):
    """'4,000만' '4천만' '5천5백만' '1억 2천만' '6천' '1억' → 만원 단위 숫자 (v13.8)"""
    total, seen = 0.0, False
    for num, unit in _KOR_TOK.findall(text):
        try:
            v = float(num.replace(",", ""))
        except ValueError:
            continue
        seen = True
        if unit == "억":
            total += v * 10000
        elif unit == "천":
            total += v * 1000
        elif unit == "백":
            total += v * 100
        else:                      # '만' 또는 단위 없음(만원 단위 그대로)
            total += v
    return total if seen else None


def extract_income(question):
    """v13.8(F3): [1단계 소득 슬롯] 질문에서 소득 금액과 소득 유형을 결정적으로 뽑는다.
    LLM 추출기가 '종합소득금액'을 총급여로 못 잡아 계산기가 통째로 건너뛰어진 실측(F3) 대응.
    반환: (만원, '총급여'|'종합소득') 또는 (None, None)."""
    m = _INC_KEY.search(question)
    if not m:
        return None, None
    v = parse_man(m.group(2))
    if v is None or not (1000 <= v <= 100000):      # 연 소득 범위 밖(월급 500만 등)은 LLM 추출에 맡김
        return None, None
    if re.search(r"(?:월|매달|매월)\s*" + re.escape(m.group(1)[:2]), question):   # '월 급여 500만원'
        return None, None
    kind = "종합소득" if re.search(r"종합\s*소득", m.group(1)) else "총급여"
    return v, kind


def fmt_credit(v):
    """v13.17: 공제액 기준 표기 — 정수면 '99', 아니면 반올림(사사오입) 소수 첫째 자리 '140.3'. 카드·요약·본문 통일."""
    if abs(v - round(v)) < 0.005:
        return f"{int(round(v)):,}"
    return f"{math.floor(v * 10 + 0.5) / 10:,.1f}"


def fallback_answer(question, used, calc_vals=None, pf_hits=None):
    """v13.20: 답변 생성 LLM 호출이 429 등으로 끝내 실패했을 때의 결정적 대체 답변.
    (실측 error.log: 429 최종 실패 → '일시적인 오류' 문구만 나가 그 문항이 통째로 0점)
    - 계산기가 돌았으면: 코드가 만든 한 줄 요약(정확한 공제액)을 그대로 답한다.
    - 아니면: 검색 상위 자료 원문 발췌를 출처와 함께 안내한다(재해석·요약 없음).
    정상 경로에서는 절대 호출되지 않는다."""
    parts = []
    if calc_vals:
        try:
            parts.append(calc_summary_line(calc_vals))
            parts.append("위 금액은 문서에 명시된 세액공제 한도(연금저축 600만원, 연금저축과 IRP 합산 "
                         "900만원)와 소득 구간별 공제율을 적용해 계산한 예상 세액공제액입니다.")
        except Exception:
            pass
    elif pf_hits:
        # v13.21: 정답표 상품이 질문에 있으면 문서 확인값을 그대로 답한다(자료 발췌보다 정확)
        for f in pf_hits:
            ln = f"{f['name']}의 위험등급은 {f['grade']}입니다."
            if f.get("fee"):
                ln += f" 보수: {f['fee']}."
            parts.append(ln + f" (출처: {f['src']})")
        parts.append("위 값은 제공된 자료에서 직접 확인된 내용이며, 그 밖의 속성은 자료에서 확인되지 않습니다.")
    else:
        parts.append(("현재 요청이 몰려 상담 답변 생성이 지연되고 있어, " if _recent_429() else "생성된 답변에서 확인된 내용이 충분하지 않아, ")
                     + "질문과 가장 관련 있는 자료 원문을 먼저 안내드립니다.")     # v13.51: 429가 아닐 때는 중립 문구
        # 질문 어휘(2자 이상)가 많이 겹치는 청크를 앞에 — 키워드 검색만 남은 상황에서 주제 이탈 완화
        _qt = [w for w in re.findall(r"[가-힣A-Za-z0-9]{2,}", question) if w not in ("알려주세요", "알려줘", "무엇", "어떻게")]
        _ranked = sorted(used or [], key=lambda c: -sum(1 for w in _qt if w in c.get("text", "")))
        for c in _ranked[:2]:
            t = re.sub(r"\s+", " ", c.get("text", "")).strip()
            if len(t) > 600:
                cut = t.rfind(". ", 300, 600)
                t = t[:cut + 1] if cut > 0 else t[:600] + "…"
            if t:
                parts.append(f"(출처: {c.get('source', '')}) {t}")
    return "\n\n".join(parts)


def calc_summary_line(c):
    """v13.8: [5단계 결과 출력] 계산기 값으로 만든 한 줄 요약 — 답변 맨 앞에 코드가 고정한다.
    LLM이 본문에서 어떤 표기를 쓰든 첫 줄은 결정적 계산 결과다(소득유형→세율→계좌별 한도→대상액→공제액)."""
    inc = c.get("inc_label", "총급여")
    sal = c.get("salary")
    band = c.get("band", "").replace(inc, "", 1).strip().replace(" (", ", ").rstrip(")")
    head = f"{inc} {int(sal):,}만원({band}) → 공제율 {c['rate_txt']}" if sal else f"공제율 {c['rate_txt']}"
    paid, base = int(c["paid"]), int(c["base"])
    sub = c.get("subcap")
    if sub:
        mid = (f"납입 {paid:,}만원(연금저축 {int(sub[0]):,} + IRP {int(sub[1]):,}) → 공제 대상 {base:,}만원"
               f"(연금저축분은 600만원까지)")
    elif paid > base and c.get("accounts") and c["accounts"][0] > 0 and c["accounts"][1] > 0:
        # v13.30(D9): 계좌별로 어느 금액이 대상인지 명시 — 연금저축 500 + IRP 400 = 900, IRP 100은 합산 한도 초과
        _a0, _a1 = int(c["accounts"][0]), int(c["accounts"][1])
        _q1 = min(_a0, 600); _q2 = int(base) - _q1
        mid = (f"납입 {paid:,}만원(연금저축 {_a0:,} + IRP {_a1:,}) → 공제 대상 {base:,}만원(연금저축 {_q1:,} + IRP {_q2:,}; "
               f"합산 한도 {int(c['limit']):,}만원 초과 {paid - base:,}만원은 대상 아님)")
    elif paid > base:
        mid = f"납입 {paid:,}만원 → 공제 대상 {base:,}만원(한도 {int(c['limit']):,}만원, 초과 {paid - base:,}만원은 대상 아님)"
    else:
        mid = f"납입 {paid:,}만원 → 공제 대상 {base:,}만원(한도 {int(c['limit']):,}만원 이내)"
    # '|'는 표 후처리가 표 행으로 오인하므로 쓰지 않는다
    _cr_txt = fmt_credit(c['credit'])
    return (f"계산 결과 요약: {head} / {mid} / 예상 세액공제액 약 {_cr_txt}만원"
            f"(= {base:,}만원 × {c['rate_txt']})")


def calc_pension_tax_credit(salary, paid, limit=900, limit_label="연금저축+IRP 합산",
                            subcap=None, income_kind="총급여"):
    """연금계좌 세액공제 계산기 — 문서 기준 반영
    salary: 총급여(만원), paid: 연간 납입액(만원), limit: 상품별 공제 한도(만원)
    subcap: (연금저축, IRP) 계좌별 금액 — 연금저축분 600만원 하위한도 적용 (v13.7)
    income_kind: '총급여'(경계 5,500) | '종합소득'(경계 4,500) (v13.7)"""
    LIMIT = limit
    thr = 4500 if income_kind == "종합소득" else 5500
    inc_label = "종합소득금액" if income_kind == "종합소득" else "총급여"
    if salary <= thr:
        rate, rate_txt = 0.165, "16.5%"
        band = f"{inc_label} {thr:,}만원 이하"
    else:
        rate, rate_txt = 0.132, "13.2%"
        band = f"{inc_label} {thr:,}만원 초과"
    if income_kind == "종합소득":
        band += " (총급여 5,500만원 " + ("이하" if salary <= thr else "초과") + "에 해당)"
    sub_line = None
    if subcap and subcap[0] > 600:
        ps, irp = subcap
        base = min(min(ps, 600) + irp, LIMIT)
        sub_line = (f"- 연금저축 납입 {int(ps):,}만원 중 세액공제 대상은 600만원까지 → "
                    f"600만원 + IRP {int(irp):,}만원 = 공제 대상 {int(base):,}만원 "
                    f"(합산 한도 {int(LIMIT):,}만원 이내). 합산 납입액 {int(paid):,}만원 전체가 "
                    f"대상인 것이 아니다.")
    else:
        base = min(paid, LIMIT)
    credit = base * rate
    lines = [
        "[세액공제 계산기 결과]",
        f"- {inc_label}: {int(salary):,}만원 → {band} → 공제율 {rate_txt} (지방소득세 포함)",
        f"- 연간 납입액: {int(paid):,}만원 → 공제 대상 금액: {int(base):,}만원 "
        f"({limit_label} 세액공제 한도 {int(LIMIT):,}만원 적용)",
    ]
    if sub_line:
        lines.append(sub_line)
    lines.append(f"- 예상 세액공제액: {int(base):,}만원 × {rate_txt} = 약 {fmt_credit(credit)}만원")
    if paid > base:
        lines.append(f"- 참고: 공제 대상({int(base):,}만원)을 초과한 {int(paid - base):,}만원은 "
                     f"세액공제 대상이 아님")
    # v9.13: 답변을 코드로 검증하기 위해 계산 값도 함께 돌려준다
    return "\n".join(lines), {"paid": paid, "base": base, "limit": LIMIT,
                              "rate": rate, "rate_txt": rate_txt, "credit": credit,
                              "subcap": subcap if sub_line else None,
                              "accounts": subcap,            # v13.22: 계좌별 원금액(하위한도 미적용이어도 보존)
                              "salary": salary, "inc_label": inc_label, "band": band}


# v9.13: LLM이 계산기 결과를 무시하고 다른 숫자를 쓰는 문제를 코드로 교정한다.
#   실제 오류: 400만+300만=700만인데 답변이 '합산 900만원 x 13.2% = 118.8만원'
#   → 프롬프트 지시만으로는 막히지 않아 계산식 자체를 정규식으로 바로잡는다.
_CALC_PAT = re.compile(
    r"\**([\d,]+)\s*만\s*원?\**\s*[x\u00d7X*]\s*\**([\d.]+)\s*%\**\s*=\s*\**\s*(?:약\s*)?\**([\d,.]+)\s*만\s*(?:(\d)\s*천\s*)?원?\**")
# v13.17: '= **39.6만 원**'처럼 마크다운 굵게가 식에 붙어 있으면 교정이 통째로 건너뛰어졌다(실측 E7·M3b·G2).
#   굵게는 맨 마지막에 지워지므로 최종 답변엔 틀린 식만 깨끗하게 남았다 → 식 정규식이 **를 허용한다.
# v13.8(G2): '= 118만8천원'처럼 'N만 M천원' 표기의 결과값을 118이 아니라 118.8로 읽는다(글리치 방지)


def _calc_c(m):
    c = float(m.group(3).replace(",", ""))
    if m.lastindex and m.lastindex >= 4 and m.group(4):
        c += int(m.group(4)) / 10
    return c


def enforce_calc(ans, calc):
    """계산기가 돌았을 때 답변 속 계산식을 계산기 값으로 강제 교정"""
    if not calc:
        return ans, ""
    base, rate_txt, credit = calc["base"], calc["rate_txt"], calc["credit"]
    ctxt = fmt_credit(credit)                       # v13.17: 답변 안 공제액 기준 표기(카드·요약과 동일)
    correct = f"{int(base):,}만원 \u00d7 {rate_txt} = 약 {ctxt}만원"
    cnt = [0]
    # v13.22: 코드가 고정한 요약 줄은 교정 대상이 아니다 — 떼어뒀다가 맨 앞에 되붙인다.
    #   (실측 E7·D9: 2차 교정 패스의 '한도 모순 문장 제거'가 요약 줄(공제액<한도, '한도' 포함)을 지웠다)
    _sum_keep = ""
    _sl = [ln for ln in ans.split("\n") if ln.startswith("계산 결과 요약:")]
    if _sl:
        _sum_keep = _sl[0]
        ans = "\n".join(ln for ln in ans.split("\n") if not ln.startswith("계산 결과 요약:")).lstrip("\n")
    def _reattach(a):
        return (_sum_keep + "\n\n" + a.lstrip("\n")) if _sum_keep else a
    # v13.22(D9): 계좌별 하위한도가 있으면 '올바른 분해'는 (연금저축분 min(납입,600), IRP분 = 대상액-연금저축분) 하나뿐
    _sub0 = calc.get("accounts") or calc.get("subcap")
    if _sub0 and (float(_sub0[1]) <= 0 or float(_sub0[0]) <= 0):
        _sub0 = None                                              # 한 계좌뿐이면 분해 없음
    _p1 = min(float(_sub0[0]), 600.0) if _sub0 else None
    _p2 = (base - _p1) if _sub0 else None
    if _sub0 and _p2 <= 0.5:
        _sub0 = None
    def _eq(a_, c_=None):
        c_ = a_ * calc["rate"] if c_ is None else c_
        return f"{int(a_):,}만원 \u00d7 {rate_txt} = 약 {fmt_credit(c_)}만원"

    # v13.17(D9): '500만원×16.5%=82.5만원 + 400만원×16.5%=66만원'처럼 대상액을 나눠 계산한 부분식은
    #   (산술이 맞고 부분들의 합이 대상액이면) 정상이므로 보존한다. 그 외 대상액·세율·결과가 어긋난 식만 교체.
    _parts = []
    for _m in _CALC_PAT.finditer(ans):
        try:
            _parts.append(float(_m.group(1).replace(",", "")))
        except ValueError:
            pass
    def _is_partial(a):
        if a >= base - 0.5:
            return False
        others = list(_parts)
        for i, b in enumerate(others):                  # 자기 자신은 한 번만 제외(300+300=600 자기합 방지)
            if abs(b - a) < 0.5:
                others.pop(i)
                break
        return any(abs((a + b) - base) < 0.5 for b in others)

    def _fix(m):
        try:
            a = float(m.group(1).replace(",", ""))
            r = float(m.group(2))
            c = _calc_c(m)
        except ValueError:
            return m.group(0)
        if abs(a - base) < 0.5 and abs(r - calc["rate"] * 100) < 0.01 \
                and abs(c - credit) < 0.06:
            return m.group(0)          # 계산기와 일치 → 그대로 둔다
        _lbl = ans[max(0, m.start() - 40):m.start()]
        _lbl = "IRP" if re.search(r"IRP|퇴직연금", _lbl) and not re.search(r"연금저축[^\n]{0,12}$", _lbl) else \
               ("PS" if "연금저축" in _lbl else "")
        if _sub0 and abs(r - calc["rate"] * 100) < 0.01 and abs(a * r / 100 - c) < 0.06 \
                and ((abs(a - _p1) < 0.5 and _lbl != "IRP") or (abs(a - _p2) < 0.5 and _lbl != "PS")):
            return m.group(0)          # v13.22: 계좌별 올바른 부분식(연금저축분·IRP분) → 보존
        if _sub0 and a < base - 0.5:
            if _lbl == "IRP":
                cnt[0] += 1
                return _eq(_p2)        # v13.22(D9): 'IRP 500만원×16.5%' → IRP분(대상액-연금저축분)으로
            if _lbl == "PS":
                cnt[0] += 1
                return _eq(_p1)
            cnt[0] += 1
            return correct             # 계좌 라벨이 없으면 합계 정답식으로(M3b '600만 원 + 250만 원×16.5%' 줄 교정과 연동)
            # v13.22(D9): 계좌 금액을 그대로 곱한 틀린 부분식('IRP 500만원×16.5%=82.5') → 올바른 분해식 한 줄로
            cnt[0] += 1
            return (f"연금저축 {_eq(_p1)}, IRP {_eq(_p2)} (합계 {correct})")
        if not _sub0 and abs(r - calc["rate"] * 100) < 0.01 and abs(a * r / 100 - c) < 0.06 and _is_partial(a):
            return m.group(0)          # 올바른 부분 분해식 → 보존
        cnt[0] += 1
        return correct

    ans = _CALC_PAT.sub(_fix, ans)
    ans = re.sub(r"\(\s*십만\s*원\s*단위\s*\)", "(만원 단위)", ans)   # v13.17(G2): 단위 오기

    # (2) '한도(900만원)를 납입액으로 착각한' 값이 본문에 남아 있으면 바로잡는다
    wrong = calc["limit"] * calc["rate"]
    if abs(wrong - credit) > 0.05:
        wpat = re.compile(r"(?<![\d.])" + re.escape(f"{wrong:,.1f}") + r"\s*만\s*원?")
        ans, k = wpat.subn(f"{ctxt}만원", ans)
        cnt[0] += k

    # (3) '합산하여 900만원' 처럼 납입액을 한도로 바꿔 말한 문장을 통째로 교체
    _sub = calc.get("subcap")
    if calc["paid"] < calc["limit"] or _sub:
        limit_txt = f"{int(calc['limit']):,}"
        paid_txt = f"{int(calc['paid']):,}"
        out = []
        _sub_done = False
        for sent in re.split(r"(?<=[.!?])\s+|\n", ans):
            if _sub and ("합산" in sent or "합쳐" in sent or "합해" in sent) \
                    and re.search(rf"(?:{limit_txt}|{paid_txt})\s*만\s*원", sent):
                # v13.7(D4/D5): 연금저축분 600만원 하위한도 — '합산 900만원 꽉 채움' 결론을 계산값으로 교체
                #   (첫 문장만 교체, 같은 취지의 뒷문장은 중복이므로 제거)
                if not _sub_done:
                    out.append(f"연금저축 납입액 {int(_sub[0]):,}만원 중 세액공제 대상은 600만원까지이므로, "
                               f"IRP {int(_sub[1]):,}만원을 더한 세액공제 대상 금액은 {int(base):,}만원입니다"
                               f"(합산 한도 {limit_txt}만원).")
                    _sub_done = True
                cnt[0] += 1
            elif not _sub and ("합산" in sent or "합쳐" in sent or "합해" in sent) \
                    and re.search(limit_txt + r"\s*만\s*원", sent):
                out.append(f"연금저축과 IRP를 합산한 납입액은 {int(calc['paid']):,}만원으로, "
                           f"세액공제 한도({limit_txt}만원) 이내입니다.")
                cnt[0] += 1
            else:
                out.append(sent)
        ans = "\n".join(out)

    # v13.17(E7·D9): 계산기와 모순되는 한도 서술 정리 — 옛 규정(고소득자 연금저축 한도 300만원)·
    #   '전액 공제 불가'(대상액=납입액인데)·'한도를 초과하지 않기 때문'(납입액>한도인데) 문장은 제거.
    _sents = re.split(r"(?<=[.!?])(?<!\d\.)\s+|\n", ans)
    _keep = []
    for _s in _sents:
        _n = re.sub(r"\s+", "", _s)
        drop = False
        _amts = [float(x.replace(",", "")) for x in re.findall(r"(\d[\d,]*(?:\.\d+)?)\s*만\s*원", _s)]
        _okv = (calc["paid"], base, credit, calc["paid"] - base, calc.get("salary") or -1) + \
               ((_p1, _p2, float(_sub0[0]), float(_sub0[1])) if _sub0 else ())   # v13.22: 초과분·공제액·계좌별 금액은 모순 아님
        if re.search(r"한도|제한", _s) and any(0 < v < calc["limit"] - 0.5 and v not in (600, 900, 1800)
                                              and all(abs(v - o) > 0.11 for o in _okv) for v in _amts):
            drop = True                                       # v13.19(E7): 한도보다 작은 금액을 '한도/제한'으로 서술(옛 규정 300만원 등)
        elif re.search(r"(?:소득이\s*높|고소득|소득\s*구간|소득에\s*따라)[^.]{0,20}(?:한도|제한)", _s):
            drop = True                                       # 현행 한도는 소득과 무관
        elif "소득구간에따라세액공제한도가다르" in _n or "소득에따라세액공제한도가다르" in _n:
            drop = True                                       # 현행 한도는 소득과 무관(600/900)
        elif abs(base - calc["paid"]) < 0.5 and re.search(r"전액[^.]{0,12}(?:받을수없|공제되지않|공제받을수없)", _n):
            drop = True                                       # 납입액 전부가 대상인데 '전액 불가'
        elif calc["paid"] > calc["limit"] + 0.5 and re.search(r"초과하지않", _n) and f"{int(calc['limit']):,}만" in _s.replace(" ", ""):
            _s = (f"합산 납입액 {int(calc['paid']):,}만원은 세액공제 한도 {int(calc['limit']):,}만원을 초과하므로 "
                  f"{int(calc['limit']):,}만원까지만 공제 대상입니다.")
            cnt[0] += 1
        if not drop:
            # v13.22(E7): '세액공제 대상 금액은 300만원이므로' — 대상액 필드가 계산기와 다르면 값만 교정
            def _tgt_fix(m):
                v = float(m.group(2).replace(",", ""))
                if v in (600.0, 900.0, 1800.0) or (_sub0 and (abs(v - _p1) < 0.5 or abs(v - _p2) < 0.5)):
                    return m.group(0)                          # 한도·계좌별 대상액 서술은 그대로
                if abs(v - base) > 0.5 and v < calc["limit"] + 0.5:
                    cnt[0] += 1
                    return f"{m.group(1)}{int(base):,}만원"
                return m.group(0)
            _s = re.sub(r"(공제\s*대상(?:\s*금액)?[은는이가]?\s*)(\d[\d,]*)\s*만\s*원", _tgt_fix, _s)
            # v13.22(D9): 계좌별 식이 있는 줄의 라벨 금액('연금저축 600만 원에 대한 공제액: …')이 질문 금액과 다르면 교정
            if _sub0 and "\u00d7" in _s:
                def _lbl_fix(m):
                    _want = float(_sub0[0]) if m.group(1) == "연금저축" else float(_sub0[1])
                    _part = _p1 if m.group(1) == "연금저축" else _p2
                    if abs(float(m.group(2).replace(",", "")) - _want) > 0.5:
                        cnt[0] += 1
                        return f"{m.group(1)} {int(_want):,}만원{m.group(3)}"
                    if _part is not None and _part < _want - 0.5 and "중 공제 대상" not in m.group(0):
                        cnt[0] += 1                        # v13.30(D9): 'IRP 500만 원에 대한' → 'IRP 500만원 중 공제 대상 400만원에 대한'
                        return f"{m.group(1)} {int(_want):,}만원 중 공제 대상 {int(_part):,}만원{m.group(3)}"
                    return m.group(0)
                _s = re.sub(r"(연금저축|IRP)\s*(\d[\d,]*)\s*만\s*원(\s*(?:에\s*대한|납입|을|를))", _lbl_fix, _s)
            # v13.22(D9): 질문의 계좌별 납입액과 다른 금액으로 '연금저축 A, IRP B 납입' 서술 → 질문과 모순이므로 제거
            if _sub0 and "납입" in _s:
                _ma = re.search(r"연금저축(?:에|은|는|의)?\s*(\d[\d,]*)\s*만\s*원", _s)
                _mb = re.search(r"IRP(?:에|은|는|의)?\s*(\d[\d,]*)\s*만\s*원", _s)
                if _ma and _mb and abs(float(_ma.group(1).replace(",", "")) - float(_sub0[0])) > 0.5 \
                        and abs(float(_mb.group(1).replace(",", "")) - float(_sub0[1])) > 0.5:
                    drop = True
        if drop:
            cnt[0] += 1
            continue
        _keep.append(_s)
    ans = "\n".join(_keep)

    # v13.8(F3): 반대 소득 구간으로 계산한 공제액(예: 종합소득 5,000만 → 16.5%로 99.0만원)이 본문에
    #   남아 있으면 공제 문맥에서만 계산기 값으로 교정하고, '반대 세율을 적용한 결과' 단정 문장은
    #   조건문(…면/경우)이 아닐 때만 계산기 판정 문장으로 교체한다.
    _other_rate = 0.132 if abs(calc["rate"] - 0.165) < 1e-6 else 0.165
    _other_txt = "13.2%" if _other_rate == 0.132 else "16.5%"
    _other_credit = base * _other_rate
    if abs(_other_credit - credit) > 0.05:
        _oc = f"{_other_credit:,.1f}"
        _forms = [re.escape(_oc)] + ([re.escape(f"{int(_other_credit):,}")] if abs(_other_credit - int(_other_credit)) < 0.04 else [])
        def _oc_fix(m):
            if re.search(r"공제|세액|환급|돌려", ans[max(0, m.start() - 40):m.start()]):
                cnt[0] += 1
                return f"약 {ctxt}만원"
            return m.group(0)
        for _f in _forms:
            ans = re.sub(rf"(?<![\d.,])(?:약\s*)?{_f}\s*만\s*원", _oc_fix, ans)
    if calc.get("salary") and _other_txt in ans:
        _sents = re.split(r"(?<=[.!?])\s+|\n", ans)
        _new = []
        for _s in _sents:
            if _other_txt in _s and re.search(r"적용|해당", _s) \
                    and not re.search(r"면\b|면,|면 |경우|라면|때는|시에는|:", _s) \
                    and calc["rate_txt"] not in _s:
                _inc = calc.get("inc_label", "총급여")
                _bd = calc.get("band", "").replace(_inc, "", 1).strip().replace(" (", ", ").rstrip(")")
                _new.append(f"{_inc} {int(calc['salary']):,}만원은 {_bd}에 해당하므로 "
                            f"세액공제율은 {calc['rate_txt']}입니다.")
                cnt[0] += 1
            else:
                _new.append(_s)
        ans = "\n".join(_new)

    # v13.16(M3b): '600만 원 + 850만원 × 16.5% = 약 140.2만원500원'처럼 교정된 식 앞뒤에 잘못된 덧셈·잔여 숫자가
    #   붙어 있으면 그 줄을 정답 식 한 줄로 교체한다(식 자체가 틀린 구조였던 경우).
    _lines = ans.split("\n")
    for _i, _ln in enumerate(_lines):
        if (correct in _ln or (_sub0 and (_eq(_p1) in _ln or _eq(_p2) in _ln))) \
                and (re.search(r"\+\s*[\d,]+\s*만\s*원?\s*[x\u00d7X*]", _ln)
                     or re.search(r"만\s*원\s*\d", _ln)):
            _lead = re.match(r"^(\s*(?:[-*•·]\s*|\d+[.)]\s*)?)", _ln).group(1)
            _lines[_i] = f"{_lead}예상 세액공제액: {correct}"
            cnt[0] += 1
    ans = "\n".join(_lines)
    # v13.16(M3b): 공제 결론 문맥(세액공제액·공제액·돌려받·예상 금액)에 계산기 정답과 다른 '공제액처럼 보이는' 금액
    #   (대상액의 10~20% 범위)이 남아 있으면 정답으로 치환. 납입액·한도(범위 밖)는 건드리지 않는다.
    _AMT = re.compile(r"(\d[\d,]*)\s*만\s*(?:(\d)\s*천\s*(?:(\d{3})\s*)?)?원|(\d[\d,]*\.\d+)\s*만\s*원")
    def _amt_val(m):
        if m.group(4): return float(m.group(4).replace(",", ""))
        v = float(m.group(1).replace(",", ""))
        if m.group(2): v += int(m.group(2)) / 10
        if m.group(3): v += int(m.group(3)) / 10000
        return v
    _lo, _hi = base * 0.05, base * 0.20               # v13.17: 옛 한도(300만)로 계산한 39.6 같은 값도 범위 안
    _part_ok = {round(_p1 * calc["rate"], 1), round(_p2 * calc["rate"], 1)} if _sub0 else set()
    def _amt_fix(m):
        v = _amt_val(m)
        _pre = ans_line_ctx[0][max(0, m.start() - 10):m.start()]
        if re.search(r"(?:IRP|연금저축|납입|추가|한도|초과(?:된|한|하는|분)?|중)\s*(?:약\s*)?$", _pre):
            return m.group(0)                                  # 납입액·한도·초과분 금액은 대상 아님
        if re.search(r"=\s*(?:약\s*)?$", _pre) or any(abs(v - pv) < 0.06 for pv in _part_ok):
            return m.group(0)                                  # v13.22: 식의 결과값·올바른 계좌별 부분 공제액은 대상 아님
        if _lo <= v <= _hi and abs(v - credit) > 0.11:
            cnt[0] += 1
            return f"약 {ctxt}만원"
        return m.group(0)
    ans_line_ctx = [""]
    _out2 = []
    for _ln in ans.split("\n"):
        ans_line_ctx[0] = _ln
        if re.search(r"세액공제|공제액|돌려받|예상\s*금액|환급|합계|합하면|총액", _ln) and correct not in _ln \
                and not _ln.startswith("계산 결과 요약"):            # v13.19(D9): 요약 줄은 코드가 만든 것 — 불변
            _ln = _AMT.sub(_amt_fix, _ln)
            _ln = re.sub(r"약\s*약\s*", "약 ", _ln)
        _out2.append(_ln)
    ans = "\n".join(_out2)

    # v13.7(G5)+v13.17: 정답의 다른 표기(반올림 정수·소수 둘째 자리·은행가 반올림·'N만 M천원'·'.0')를 전부 기준 표기로 통일.
    #   공제 문맥(앞 40자에 공제·세액·환급·돌려)일 때만 — 납입액 등 다른 금액 오교정 방지.
    _c_canon = f"약 {ctxt}만원"
    _variants = set()
    _ci = int(credit)
    if abs(credit - _ci) > 0.04:                                   # 소수 정답: 정수 반올림들도 변형
        _variants.update({str(math.floor(credit)), str(math.ceil(credit))})
    _variants.update({f"{credit:.1f}", f"{credit:.2f}", f"{math.floor(credit*10+0.5)/10:.1f}",
                      f"{credit:.1f}".rstrip("0").rstrip("."), f"{_ci}.0"})
    _variants.discard(ctxt)
    _variants = {v for v in _variants if v}
    def _var_fix(m):
        if re.search(r"공제|세액|환급|돌려", ans[max(0, m.start() - 40):m.start()]):
            cnt[0] += 1
            return _c_canon
        return m.group(0)
    for _v in sorted(_variants, key=len, reverse=True):
        ans = re.sub(rf"(?<![\d.,])(?:약\s*)?{re.escape(_v)}\s*만\s*원", _var_fix, ans)
    # 'N만 M천원' / 'N만 M천 K백원' 형태
    _cf = int(round((credit - _ci) * 10))
    if _cf:
        ans = re.sub(rf"(?<![\d.,])(?:약\s*)?{_ci:,}\s*만\s*{_cf}\s*천\s*(?:\d{{3}}\s*)?원", _var_fix, ans)
    ans = re.sub(r"약\s*약\s*", "약 ", ans)
    ans = _reattach(ans)                                           # v13.22: 요약 줄 복원
    if cnt[0]:
        return ans, f" (계산식 코드 교정 {cnt[0]}건)"
    return ans, ""


def fix_arith(ans):
    """v13.6(K6): 결정적 산술 검증 — 계산기 실행 여부와 무관하게 답변 속 'A만원 × R% = C만원' 식의
    C를 코드로 재계산해(A×R/100) 틀리면 바로잡고, 본문에 남은 같은 틀린 값도 교정한다.
    실측 K6: 추출기가 두 계좌 납입액을 합산 못 해 계산기가 안 돌자 LLM이 900×13.2%=119.28(정답 118.8)로
    오산. 산술을 LLM에 맡기지 않는 마지막 안전망. 식이 없거나 이미 맞으면 원문 불변."""
    fixes = []

    def _f(m):
        try:
            a = float(m.group(1).replace(",", ""))
            r = float(m.group(2))
            c = _calc_c(m)
        except ValueError:
            return m.group(0)
        t = a * r / 100
        if abs(c - t) < 0.06:            # 반올림 오차 이내 = 정상
            return m.group(0)
        _tt = fmt_credit(t)              # v13.22: 요약·카드와 같은 표기(사사오입 소수 첫째 자리; 140.25→140.3)
        fixes.append((m.group(3), _tt))
        return f"{m.group(1)}만원 × {m.group(2)}% = 약 {_tt}만원"

    ans = _CALC_PAT.sub(_f, ans)
    # v13.22: 재언급 교정은 코드가 만든 요약 줄에는 적용하지 않는다(실측 D9: 부분식 500×16.5%의 교정값이
    #   요약 줄의 합계 148.5를 82.5로 덮어씀). 요약 줄은 계산기 값 그대로.
    _lines = ans.split("\n")
    for _i, _ln in enumerate(_lines):
        if _ln.startswith("계산 결과 요약:"):
            continue
        for wrong, right in fixes:       # '총 공제액은 약 119.28만원' 같은 본문 재언급도 교정
            _ln = re.sub(r"(?<![\d.])" + re.escape(wrong) + r"(?=\s*만\s*원)", right, _ln)
        _lines[_i] = _ln
    ans = "\n".join(_lines)
    return ans, len(fixes)


def reconcile_sum_limit(ans, paid, base, limit):
    """v11.6: 소득 미상(band_vals)이라 enforce_calc가 안 돌 때, 연금저축+IRP '합산'
    맥락에서 LLM이 남긴 잘못된 결론 문장('합해/합산/분산 … 한도/대상 X만원 적용')의
    X가 계산된 공제대상(base)과 다르면 그 '문장만' 계산값 기준으로 in-place 재작성한다.
    특정 숫자('600')를 지우는 하드코딩이 아니라, 값이 어긋난 결론 문장을 값으로 교정.
    교정할 게 없으면 원문을 그대로 돌려준다(구조·다른 문장 불변)."""
    if base is None or paid is None or limit is None:
        return ans, 0
    n = [0]

    def _fix(m):
        pre, s = m.group(1), m.group(2)
        if re.search(r"합산|합해|합쳐|두 계좌|분산", s) and re.search(r"적용|대상", s):
            mv = re.search(r"(\d[\d,]*)\s*만\s*원", s)
            if mv and int(mv.group(1).replace(",", "")) != int(base):
                n[0] += 1
                return pre + (f"연금저축과 IRP 합산 납입액 {int(paid):,}만원은 세액공제 "
                              f"한도({int(limit):,}만원) 이내이므로, 세액공제 대상 금액은 "
                              f"{int(base):,}만원입니다.")
        return m.group(0)

    ans2 = re.sub(r"(\s*)([^\n.!?]+[.!?])", _fix, ans)
    return (ans2, n[0]) if n[0] else (ans, 0)


# v9.15: '연금저축 단독 900만원'처럼 한도를 뭉뚱그리는 오류 (회귀 R02 재발) 대응.
#   문서로 검증된 한도 구조를 카드로 만들어 참고 문서 맨 위에 못박는다.
