def find_must_chunks(question, exclude, limit_total=2):
    """질문이 특정 주제면 필요한 청크를 코퍼스에서 직접 찾아온다."""
    seen = {c["text"] for c in exclude}
    out = []
    for q_any, q_any2, need, lim in MUST_CHUNKS:
        if not any(k in question for k in q_any):
            continue
        if q_any2 and not any(k in question for k in q_any2):
            continue
        got = 0
        for c in chunks:
            if c["text"] in seen or any(c["text"] == o["text"] for o in out):
                continue
            if any(k in c["text"] for k in need):
                out.append(c)
                got += 1
                if got >= lim:
                    break
        if out:
            break
    return out[:limit_total]



def find_limit_evidence(exclude):
    """v13.29(계약 3 — 계산 근거): 계산기·한도 카드가 쓰는 한도(연금저축 600만원·합산 900만원)가 사용 근거 문서 안에 실제로 있어야
    출처가 성립한다. 없으면 '세액공제'+'900만원'+'600만원'이 함께 있는 청크(안내 문서 docNN 우선)를 하나 찾아 돌려준다."""
    seen = {c["text"] for c in exclude}
    for c in exclude:
        t = re.sub(r"\s+", "", c.get("text", ""))
        if "세액공제" in t and ("900만원" in t or "900만" in t) and ("600만원" in t or "600만" in t):
            return None                                   # 이미 근거 안에 있음
    best = None
    for c in chunks:
        if c["text"] in seen:
            continue
        t = re.sub(r"\s+", "", c.get("text", ""))
        if "세액공제" in t and ("900만원" in t or "900만" in t) and ("600만원" in t or "600만" in t):
            if str(c.get("source", "")).startswith("doc"):
                return c
            best = best or c
    return best


def find_fee_rows(sources, exclude, limit=2):
    """v9.20: 보수표는 숫자 나열이라 임베딩 유사도가 낮아 상위에 못 든다.
    (실측: 질문과 같은 문서인데도 17위) → 검색된 문서 안에서 보수표 청크를 직접 찾아 넣는다."""
    seen = {c["text"] for c in exclude}
    cand = []
    for c in chunks:
        if c["source"] not in sources or c["text"] in seen:
            continue
        t = c["text"]
        if "총보수" not in t or len(_DEC.findall(t)) < 6:
            continue
        cand.append(c)
    # 구성항목이 다 있는 상세표(신탁업자 포함)를 먼저, 숫자가 많은 것을 먼저
    cand.sort(key=lambda c: (("신탁업자" in c["text"]), len(_DEC.findall(c["text"]))),
              reverse=True)
    return cand[:limit]


# v9.21: 숫자표를 원문 그대로 주면 항목을 빠뜨린다(실측: 일반사무관리 0.02% 누락으로
#   0.72+0.7+0.03=1.45 ≠ 총보수 1.47). → 세액공제 계산기처럼 코드가 표를 읽어 카드로 만든다.
_FEE_FIRSTDEC = re.compile(r"\d+\.\d+")
_FEE_TOKEN = re.compile(r"\d+(?:\.\d+)?%?|[-–—]")
_FEE_CLSHEAD = re.compile(r"종류\s*([A-Za-z][A-Za-z0-9\-]*)")
_FEE_ITEMS = ["집합투자업자 보수", "판매회사 보수", "신탁업자 보수", "일반사무관리회사 보수"]


def _fnum(t):
    t = str(t).replace("%", "")
    try:
        return float(t)
    except ValueError:
        return None


def build_fee_card(text, source, limit=14):
    """보수표 청크 → 클래스별 구성항목·총보수를 정리한 카드 (없으면 None)"""
    rows = []
    for seg in re.split(r"(?=종류\s*[A-Za-z])", text):
        m = _FEE_CLSHEAD.match(seg.strip())
        if not m:
            continue
        d = _FEE_FIRSTDEC.search(seg)
        if not d:
            continue
        toks = _FEE_TOKEN.findall(seg[d.start():])
        if len(toks) < 9:
            continue
        n = [_fnum(t) for t in toks[:9]]
        if n[4] is None or not (0 < n[4] < 10):
            continue
        if any(v is not None and v > 10 for v in n[:5]):   # 수익률·연도 오인 방지
            continue
        rows.append((m.group(1), n))
        if len(rows) >= limit:
            break
    if not rows:
        return None
    out = [f"[보수 구성표 — 출처: {source}]",
           "※ 문서의 표를 코드가 그대로 옮긴 것이다. 항목을 빠뜨리거나 값을 바꾸지 마라.",
           "※ 클래스(종류)마다 값이 다르므로 반드시 어느 클래스 기준인지 밝혀서 인용하라."]
    for cls, n in rows:
        parts = [f"{_FEE_ITEMS[i]} {n[i]:g}%" if n[i] is not None
                 else f"{_FEE_ITEMS[i]} 없음" for i in range(4)]
        tot = round(sum(v for v in n[:4] if v is not None), 4)
        line = f"- 종류{cls}: " + " / ".join(parts) + f" → 총보수 {n[4]:g}%"
        if n[5] is not None:
            line += f" / 기타비용 {n[5]:g}%"
        if n[6] is not None:
            line += f" / 총보수·비용 {n[6]:g}%"
        line += f"   [구성항목 합계 {tot:g}%]"
        out.append(line)
    return "\n".join(out)


# v9.23: '가장 낮습니다', 'A가 B보다 높습니다' 같은 순위·우열 단정을 프롬프트로 네 번
#   막았으나 계속 재발했다. → 최상급 요구가 감지된 답변에 한해 코드로 잘라낸다.
#   단, '단정할 수 없다'처럼 부정으로 끝나는 문장은 오히려 필요하므로 남긴다.
_RANK_CLAIM = re.compile(
    r"(?:보다\s*(?:더\s*)?(?:낮|높|저렴|비싸|많|적)|"
    r"가장\s*(?:낮|높|저렴|비싸|적|많)|제일\s*(?:낮|높|저렴)|최저|최고)")
_RANK_NEG = re.compile(
    r"없|어렵|아닙|못하|말하기|판단할 수|단정|확인되지|알 수 없|비교할 수|"
    r"위해|찾기|비교해|살펴|알아보|하겠습니다|드리겠습니다")   # 서두·부정문은 유지


def strip_rank_claims(ans, active):
    """순위·우열을 단정한 문장을 제거한다. (표 줄은 건드리지 않음)"""
    if not active:
        return ans, 0
    removed, out, _fee_rm = 0, [], False
    for line in ans.split("\n"):
        if "|" in line or not line.strip():      # 표·빈 줄은 그대로
            out.append(line)
            continue
        sents = re.split(r"(?<![0-9]\.)(?<=[.!?])\s+", line)
        keep = []
        for sent in sents:
            if _RANK_CLAIM.search(sent) and not _RANK_NEG.search(sent):
                removed += 1
                _fee_rm = _fee_rm or bool(re.search(r"보수|수수료|비용", sent))
                continue
            keep.append(sent)
        out.append(" ".join(keep))
    if not removed:
        return ans, 0
    ans = re.sub(r"\n{3,}", "\n\n", "\n".join(out)).strip()
    # 근거를 남기기 위해 한 문장으로 대체 (이미 같은 취지의 문장이 있으면 넣지 않는다)
    # v13.48(G11 실측): 총보수 고지는 지운 문장이 보수·수수료 순위였을 때만 — 그 외 최상급 질문은 (1-3) 일반 순위 고지가 맡는다
    if _fee_rm and not re.search(r"순위[^\n]{0,20}(없|확인)", ans):
        ans += ("\n\n제공된 자료에는 상품 간 총보수 순위 비교표가 없고, 값의 기준(클래스·표)도 "
                "서로 달라 어느 상품이 더 낮은지는 단정할 수 없습니다.")
    return ans, removed


# v9.26: 제공 문서에서 확인된 단위 오표기.
#   audit_numbers.py 전수 점검으로 찾았고, 문서 안의 다른 수치로 교차 검증했다.
#     · doc41.docx  "148만 5천만원(=900만원 x 16.5%)" → 900만×16.5% = 1,485,000원
#     · doc26.docx  "26만 4천만원"  → 이 값의 30%가 같은 문단의 '7만 9,200원'과 맞으므로
#                                    26만 4천원(264,000원)이 맞다
#   ※ 우리가 임의로 '보정'하지 않는다. 원문 표기를 밝히고 계산값을 함께 제시한다.
NUMBER_NOTES = [
    {"src": "doc41.docx", "wrong": "148만 5천만원", "right": "148만 5천원",
     "basis": "900만원 × 16.5% = 1,485,000원"},
    {"src": "doc26.docx", "wrong": "26만 4천만원", "right": "26만 4천원",
     "basis": "같은 문단의 '30% 절세액 7만 9,200원'과 맞는 값은 264,000원"},
]
_NOTE_PAT = [(n, re.compile(n["wrong"].replace(" ", r"\s*"))) for n in NUMBER_NOTES]


def build_number_card(context):
    """검색된 문서에 알려진 오표기가 있으면 주의 카드를 만든다"""
    hits = [n for n, pat in _NOTE_PAT if pat.search(context)]
    if not hits:
        return None, []
    lines = ["[문서 표기 주의 — 자료의 숫자와 계산값이 다른 곳]"]
    for n in hits:
        lines.append(f"- {n['src']}에 '{n['wrong']}'으로 적혀 있으나, {n['basis']}이므로 "
                     f"계산상 '{n['right']}'이다.")
    lines.append("※ 답변에는 위 계산값만 사용하라. 사용자가 원문·표기·문서 오기를 직접 "
                 "묻지 않았다면 잘못된 원문 숫자를 답변에 그대로 옮겨 적지 마라(오기 재현 금지). "
                 "원문 오류를 밝혀야 할 때도 틀린 숫자를 반복하지 말고 '원문 표기에 단위 오류가 "
                 "있으나 계산상 금액은 …'처럼 간단히 안내하라.")
    return "\n".join(lines), hits


# v9.32: 유도성 질문의 잘못된 전제를 그대로 수긍하는 문제를 코드로 잡는다.
#   실측(H4): "총급여 5,500만원이면 13.2%" (→ 이하는 16.5%),
#             "중도해지해도 세금이 부과되지 않습니다" (→ 기타소득세 16.5%)
#   평가지표 첫 항목이 '잘못된 전제를 바로잡는가'라 실점이 크다.
_FALSE_PREMISE = [
    # (잘못된 서술 패턴, 바로잡는 문장)
    # '이하 … 16.5% … 13.2%'처럼 사이에 올바른 세율이 있으면 정상 문장이므로 건드리지 않는다
    (re.compile(r"[^\n]*5,?500\s*만\s*원?[^\n]{0,30}?(?:이하|인\s*경우|까지|정확히)"
                r"(?:(?!16\.5)[^\n]){0,40}?13\.2\s*%[^\n]*"),
     "총급여 5,500만원 이하(종합소득금액 4,500만원 이하)이면 세액공제율은 16.5%이고, "
     "이를 초과하면 13.2%입니다. 총급여가 정확히 5,500만원인 경우는 '이하'에 해당하므로 "
     "16.5%가 적용됩니다."),
    (re.compile(r"[^\n]*5,?500\s*만\s*원?[^\n]{0,30}?초과"
                r"(?:(?!13\.2)[^\n]){0,40}?16\.5\s*%[^\n]*"),
     "총급여 5,500만원을 초과하면 세액공제율은 13.2%입니다."),
    # v9.33: '**중도해지해도 세금**이 없습니다'처럼 마크다운 강조가 끼어들어도 잡히도록
    #        글자 사이에 * _ 공백을 허용한다 (실측 H4에서 이것 때문에 교정이 안 됐다)
    (re.compile(r"[^\n]*중도[\s*_]*해지[^\n]{0,40}?"
                r"(?:세금[\s*_]*이[\s*_]*부과되지[\s*_]*않|"
                r"세금[\s*_]*을?[\s*_]*(?:안[\s*_]*내|내지[\s*_]*않)|"
                r"과세[\s*_]*되지[\s*_]*않|세금[\s*_]*이[\s*_]*없)[^\n]*"),
     "중도해지하면 세액공제를 받은 납입금과 운용수익에 대해 기타소득세 16.5%가 부과됩니다. "
     "다만 세액공제를 받지 않은 납입금은 인출해도 세금이 없습니다."),
    # v13.3(CMP3): DB형을 '회사 운용 결과에 따라 퇴직금이 변한다'고 쓰는 오류 교정.
    #   문서 근거(코퍼스 실측): DB는 근로자 급여가 사전 확정(운용 결과와 무관), 회사가 적립금을
    #   운용하고 운용 손익·적립금 부담 변동은 회사(사용자) 귀속. DC는 회사 부담금 확정, 근로자 운용.
    #   '회사가 운용 + 급여가 변동'은 DB(급여 고정)에도 DC(근로자 운용)에도 맞지 않는 서술.
    #   '근로자가 운용…급여 변동'(DC 정상 서술)은 '회사' 조건 때문에 매칭되지 않아 보호됨.
    (re.compile(r"[^\n]*회사(?:의|가)?\s*운용\s*(?:결과|성과)[^\n]{0,25}?(?:퇴직금|급여)"
                r"[^\n]{0,20}?(?:변|달라|결정|좌우)[^\n]*"),
     "DB형(확정급여형)은 근로자가 받을 급여가 사전에 확정되어 운용 결과와 무관하며, 회사가 적립금을 "
     "운용하고 운용 손익은 회사에 귀속됩니다. DC형(확정기여형)은 회사 부담금이 사전에 확정되고 "
     "근로자가 직접 운용하며 운용 결과가 근로자의 급여에 반영됩니다."),
]


def fix_false_premise(ans):
    """사용자의 잘못된 전제를 수긍한 문장을 문서 기준 문장으로 교체"""
    cnt = 0
    for pat, right in _FALSE_PREMISE:
        out, n = pat.subn(right, ans)
        if n:
            ans, cnt = out, cnt + n
    return ans, cnt


# v9.33: 질문에 소득이 있는데 유형이 '세제'가 아니면 계산기가 안 돌아 세율을 틀린다.
#   실측(H2): "연봉 6천만원" 질문에 16.5%를 적용했다(5,500만원 초과이므로 13.2%).
#   → 유형과 무관하게, 소득이 보이면 세율 판정을 코드가 먼저 못박는다.
#   '총급여가 정확히 5,500만원'처럼 부사가 끼는 경우까지 잡는다
_INCOME_PAT = re.compile(
    r"(?:연봉|총급여|급여|연소득)[은는이가]?\s*(?:[가-힣]{1,4}\s*)?([\d,]+)\s*(천만|억|만)\s*원")
_TAX_WORDS = ("세액공제", "공제", "절세", "세금", "환급")


# v13.28 [답변 계약 1 — 연금소득세 연령-세율]: 질문이 '연금으로 받을 때 세금'이면 문서 확인값을 카드로 주입한다(생성·검증기가
#   같은 근거를 본다). 답변 뒤에는 age_rate_contract()가 '근거 청크가 실제로 사용됐을 때만 숫자 허용'을 강제한다.
_AGE_Q = re.compile(r"연금소득세|연금\s*수령|연금수령|연금으로\s*(?:받|수령)|수령할\s*때|받을\s*때")
_AGE_Q2 = re.compile(r"세금|세율|과세|소득세")
_AGE_NUMS = re.compile(r"\d{2}\s*세[^\n%]{0,25}?(?<![\d.])(?:5\.5|4\.4|3\.3|5|4|3)\s*%")


def age_rate_card(question):
    if _AGE_SRC and _AGE_Q.search(question) and _AGE_Q2.search(question):
        return (f"[연금소득세 연령별 세율 — 문서({_AGE_SRC}) 확인값. 이 값만 쓰고 다른 구간·세율을 만들지 말 것]\n"
                "- 만 70세 미만 5.5%, 70세 이상 80세 미만 4.4%, 80세 이상 3.3% (연금수령한도 내 수령 시, 세액공제 받은 납입금·운용수익 재원)\n"
                "- 수령 '연차'가 아니라 '연령' 기준이다. 자료에 없다고 쓰지 말 것(위 문서에 있음)")
    return None


def age_rate_contract(ans, used):
    """v13.28 [계약 1 검증]: 답변에 연령-세율 숫자가 있으면 근거 청크(70세·5.5·3.3)가 used 안에 있어야 한다.
    없으면 숫자 문장을 '확인 불가' 문장으로 차단(삭제가 아니라 대체). → (답변, 조치)"""
    if not _AGE_NUMS.search(ans):
        return ans, ""
    _texts = [re.sub(r"\s+", "", c.get("text", "")) for c in used]
    _ev = any(("70세" in t and "5.5" in t and "3.3" in t) for t in _texts)
    if _ev or _AGE_SRC:
        # v13.29: '지방소득세 포함'은 사용 근거 문서에 그 표기가 있을 때만(doc1 등) — 없으면 그 문장만 대체
        if re.search(r"지방소득세", ans) and not any("지방소득세" in t for t in _texts):
            _o, _k = [], 0
            for _ln in ans.split("\n"):
                _ss = re.split(r"(?<=[.!?])\s+", _ln)
                _kp = [x for x in _ss if not re.search(r"지방소득세", x)]
                _k += len(_ss) - len(_kp)
                if _ln.strip() and not "".join(_kp).strip():
                    continue
                _o.append(" ".join(_kp))
            if _k:
                return "\n".join(_o), f" (세율 계약: 근거 없는 지방소득세 표기 {_k}문장 제거)"
        return ans, ""
    _out, _n = [], 0
    for _ln in ans.split("\n"):
        _ss = re.split(r"(?<=[.!?])\s+", _ln)
        _kp = []
        for x in _ss:
            if _AGE_NUMS.search(x):
                _n += 1
                if not any("연령별 연금소득세율은 제공된 자료에서 확인되지 않습니다" in y for y in _kp + _out):
                    _kp.append("연령별 연금소득세율은 제공된 자료에서 확인되지 않습니다.")
            else:
                _kp.append(x)
        _out.append(" ".join(_kp))
    return "\n".join(_out), (f" (세율 계약: 근거 없는 연령-세율 {_n}문장 차단)" if _n else "")


# v13.28 [답변 계약 2 — 추천 상품 연결]: 추천 답변의 각 상품은 '상품명 ∈ 사용 근거 문서' 이고, 답변이 붙인 위험등급이 그 문서(또는
#   정답표)의 등급과 같아야 한다. 연결이 끊긴 상품의 줄은 제거하고 한 줄로 알린다(문구 치환이 아니라 주장 단위 차단).
# v13.34 [답변 계약 5 — 질문 요구사항 누락]: 질문이 명시적으로 요구한 속성(위험등급·총보수·수익률·세액공제·한도·설정액·클래스)이
#   답변에 한 번도 나오지 않으면, 정답표에 값이 있으면 그 값을, 없으면 '자료에서 확인되지 않았다'는 한 줄을 붙인다(누락 대신 명시).
#   제외 요청('수수료 얘기는 빼고')된 속성은 요구로 보지 않는다. LLM 파서 없이 결정적 슬롯.
_EXCL_NEG = r"(?:빼고|말고|제외하고|제외한\s|넘어가고|됐고|필요\s*없(?:고|으니|어서)|생략하고|건너뛰고|안\s*해도\s*(?:되니|돼서|되고))"
REQUEST_SLOTS = [
    ("위험등급", r"위험\s*등급|등급", r"\d\s*등급|(?:매우\s*)?(?:높은|낮은|보통|다소\s*높은)\s*위험|등급"),
    ("총보수", r"총\s*보수|보수|수수료", r"보수|수수료"),
    ("수익률", r"수익률", r"수익률"),
    ("세액공제", r"세액\s*공제|공제액|공제\s*금액", r"세액공제|공제"),
    ("한도", r"한도", r"한도|까지"),
    ("설정액", r"설정액|운용\s*규모", r"설정액|규모|억"),
    ("클래스", r"클래스", r"클래스|C-P|\(C|Ce\)"),
    ("운용사", r"운용사", r"자산운용|운용사"),
]


def requirement_contract(question, ans, pf_hits):
    body = ans.split("[참고 문서]")[0]
    missing = []
    for name, qpat, apat in REQUEST_SLOTS:
        if not re.search(qpat, question):
            continue
        if re.search(r"(" + qpat + r")[^\n]{0,14}?" + _EXCL_NEG, question):
            continue                                              # 제외 요청된 속성
        if re.search(apat, body):
            continue
        missing.append(name)
    if not missing:
        return ans, ""
    adds = []
    for name in missing:
        filled = False
        for f in (pf_hits or []):
            if name == "위험등급":
                adds.append(f"{f['name']}의 위험등급은 {f['grade']}입니다(출처 {f['src']})."); filled = True
            elif name == "총보수" and f.get("fee"):
                adds.append(f"{f['name']}의 보수: {f['fee']}(출처 {f['src']})."); filled = True
        if not filled:
            adds.append(f"요청하신 '{name}'은(는) 이 답변에서 확인해 드리지 못했습니다. 사용한 자료 범위에서 별도 확인이 필요합니다.")
    head, tail = (ans.split("[참고 문서]", 1) + [""])[:2]
    tail = ("[참고 문서]" + tail) if "[참고 문서]" in ans else ""
    out = head.rstrip() + "\n\n" + "\n".join(adds) + ("\n\n" + tail if tail else "")
    return out, f" (요구사항 계약: 누락 속성 {len(missing)}건 보강 — {', '.join(missing)})"


def deposit_guarantee_contract(ans, used):
    if not re.search(r"원리금\s*보장|원리금보장|예금", ans):
        return ans, ""
    _texts = [re.sub(r"\s+", "", c.get("text", "")) for c in used]
    n = 0
    out = []
    for ln in ans.split("\n"):
        if ln.lstrip().startswith("※") or "[참고 문서]" in ln:
            out.append(ln); continue
        ss = re.split(r"(?<=[.!?])\s+", ln)
        kp = []
        for st in ss:
            if re.search(r"원금과\s*(?:약정된\s*)?이자를\s*보장|원리금[이을]?\s*보장(?:해|하|되)", st) and not re.search(r"조건|따라|한도|예금자보호|보장하지|보장되지|않", st):
                st2 = re.sub(r"원금과\s*(?:약정된\s*)?이자를\s*보장해\s*주는\s*상품(?:으로|이며|입니다)?", "해당 금융기관·상품의 보장 조건에 따라 원리금이 보장되는 상품으로", st)
                if st2 == st:
                    st2 = re.sub(r"원리금[이을]?\s*보장(?:해\s*주는|하는|되는)\s*상품", "해당 금융기관·상품의 보장 조건에 따라 원리금이 보장되는 상품", st)
                if st2 == st:
                    st2 = re.sub(r"원리금[이을]?\s*보장됩니다", "해당 금융기관·상품의 보장 조건에 따라 원리금이 보장됩니다", st)
                if st2 == st:                                     # v13.44(R2 실측): '원금과 약정된 이자를 보장해주는 특성이 있어'
                    st2 = re.sub(r"원금과\s*(?:약정된\s*)?이자를\s*보장해\s*?주는", "해당 금융기관·상품의 보장 조건에 따라 원금과 이자가 보장되는", st)
                st = st2
                n += 1
            if re.search(r"중도\s*해지[^.!?]{0,20}이자[^.!?]{0,10}손실", st) and not any(("중도해지" in t or "중도상환" in t) and "이자" in t for t in _texts):
                n += 1
                continue                                          # 근거 문서에 없는 중도해지 이자 손실 서술 제거
            # v13.33(G11): '원리금보장형 상품이 가장 적합할 것입니다' → 후보 표현; 재예치·만기상환 서술은 근거 문서에 그 단어가 있을 때만
            if re.search(r"원리금\s*보장형?\s*상품이\s*(?:가장\s*)?적합", st):
                st = re.sub(r"원리금\s*보장형?\s*상품이\s*(?:가장\s*)?적합할?\s*(?:것입니다|합니다|수\s*있습니다)",
                            "자료상 원금 보장을 중시할 때 검토할 수 있는 후보는 원리금보장형 상품입니다", st)
                n += 1
            if re.search(r"재예치|만기상환", st) and not any(("재예치" in t or "만기상환" in t) for t in _texts):
                n += 1
                continue
            kp.append(st)
        if ln.strip() and not "".join(kp).strip():
            continue
        out.append(" ".join(kp))
    return "\n".join(out), (f" (원리금보장 서술 계약 {n}건)" if n else "")


_question_hint = [""]      # v13.32: recommend_contract 가 질문 성향(안정형)을 알기 위한 슬롯(answer()에서 설정)


_RC_FB_SRCS = []                                                  # v13.66: 구조화 대체 목록이 인용한 출처(출처 줄 정밀화용)


def _josa(nm):
    """v13.66: 상품명 뒤 주격 조사 — 마지막 글자의 받침으로 '은'/'는' 결정(한글·숫자), 판정 불가(영문 끝)는 '은(는)'."""
    _s = re.sub(r"[\s)\]'\"」*]+$", "", nm)
    if not _s:
        return "은(는)"
    _c = _s[-1]
    if "가" <= _c <= "힣":
        return "은" if (ord(_c) - 0xAC00) % 28 else "는"
    if _c.isdigit():
        return "은" if _c in "013678" else "는"
    return "은(는)"


def _rc_fallback_body(used, _hint_q):
    """v13.65 [추천 후보 원칙]: 후보는 '검색된 투자설명서에서 코드가 직접 읽은 (상품명, 위험등급, 출처)'만 제시한다.
    질문 성향(공격/안정)으로 등급 범위를 거르고, 정보 부족은 역질문으로 마무리한다. (LLM 호출 없음)"""
    _prof = extract_risk_profile(list(dict.fromkeys(c.get("source", "") for c in used if str(c.get("source", "")).startswith("R2_"))))
    _aggr = bool(re.search(r"공격|고수익|높은\s*수익|성장", _hint_q)); _safe = bool(re.search(r"안정|안전|원금|손해|손실", _hint_q))
    _items = sorted(_prof.items(), key=lambda kv: kv[1]["grade"])
    if _aggr:
        _items = [kv for kv in _items if kv[1]["grade"] <= 3] or _items          # 위험 높은 순(숫자 작은 순)
        _crit = "공격적 성향 조건에 맞춰, 확인된 후보 중 위험등급 숫자가 가장 낮은(위험이 가장 높은) 상품을 대표 후보로 두었습니다"
    elif _safe:
        _items = sorted([kv for kv in _items if kv[1]["grade"] >= 4] or _items, key=lambda kv: -kv[1]["grade"])   # v13.75: 위험 낮은 순
        _crit = "안정 선호 조건에 맞춰, 확인된 후보 중 위험등급 숫자가 가장 높은(위험이 가장 낮은) 상품을 대표 후보로 두었습니다"
    else:
        _crit = ""                                                            # v13.76: 성향 정보 없음 → 대표 후보를 지정하지 않는다(임의 선택 금지)
    _lines_ = []
    _RC_FB_SRCS.clear()
    for _n, _r in _items[:4]:
        _n = re.sub(r"(\d)\s+호", r"\1호", _n)                       # v13.62: 원문 띄어쓰기('1 호') 정리
        _lab = (_r.get("label") or _LABEL_BY_GRADE.get(_r["grade"], "")).replace(" ", "")
        _lines_.append(f"- {_n}: 위험등급 {_r['grade']}등급({_lab}) — 근거 문서: {_r['src']}\n - 유의: {_n}{_josa(_n)} 실적배당형으로, 투자원금과 수익(분배금)은 보장되지 않습니다.")
        _RC_FB_SRCS.append(_r["src"])
    if _lines_:
        _one = bool(re.search(r"하나|한\s*개|한\s*가지|1개", _hint_q))
        _safe_head = ("아래 후보는 모두 펀드(실적배당형)로 투자원금과 수익이 보장되지 않습니다. 원금 보장을 우선하신다면 예금 등 원리금보장형 상품군을 별도로 확인해야 합니다. " if _safe else "")   # v13.67(M2b)
        _head = (_safe_head + ("질문하신 대로 '하나'를 고르기에는 현재 정보(연령·투자성향)만으로는 부족해 특정 상품을 확정하지 않습니다. " if _one else
                  "문의하신 조건에 맞는 상품을 제공된 자료 안에서 확정하지 못했습니다. ") +
                 "검색된 투자설명서에서 코드가 직접 확인한 상품과 위험등급은 다음과 같으며, 후보로 검토하실 수 있습니다"
                 "(투자설명서의 위험등급 체계: 1등급 매우 높은 위험 ~ 6등급 매우 낮은 위험):\n\n")          # v13.66(T11): 확정 불가를 먼저, 등급 체계 출처 명시
        if _one and len(_lines_) >= 1 and not _crit:                # v13.76: 조건 없는 '하나' 요구 → 대표 지정 없이 역질문 + 성향별 예시(공격형/안정형 각 1줄)
            _by_g = sorted(_items[:len(_lines_)], key=lambda kv: kv[1]["grade"])
            _ex = []
            _hi = _by_g[0]; _lo = _by_g[-1]
            for _lab_, _kv in (("공격적 성향이면(확인된 후보 중 위험등급 숫자 최소)", _hi), ("안정 선호 성향이면(확인된 후보 중 위험등급 숫자 최대)", _lo)):
                if any(_kv is x for _, x in _ex):
                    continue
                _ex.append((_lab_, _kv))
            _ex_lines = []
            for _lab_, (_n, _r) in _ex:
                _n = re.sub(r"(\d)\s+호", r"\1호", _n)
                _lab2 = (_r.get("label") or _LABEL_BY_GRADE.get(_r["grade"], "")).replace(" ", "")
                _ex_lines.append(f"- {_lab_}: {_n} — 위험등급 {_r['grade']}등급({_lab2}), 근거 문서: {_r['src']}")
            return (_safe_head + "투자 성향·계좌 종류·투자 기간이 확인되지 않아 특정 상품을 '하나'로 지정하지 않습니다. "
                    "계좌 종류(연금저축/IRP)·투자 기간·손실 감내 수준을 알려주시면 제공된 자료에서 확인되는 상품 중 하나로 조건부로 좁혀 드리겠습니다.\n\n"
                    "조건이 정해지면 이렇게 좁혀집니다(예시, 추천 확정 아님 — 투자설명서의 위험등급 체계: 1등급 매우 높은 위험 ~ 6등급 매우 낮은 위험):\n" + "\n".join(_ex_lines) +
                    "\n - 유의: 위 상품은 모두 실적배당형으로, 투자원금과 수익(분배금)은 보장되지 않습니다.")
        if _one and len(_lines_) >= 1:                              # v13.74/76(T11): 조건부 대표 후보(동일 등급 동점이면 우열 없이 함께), 나머지는 비교 후보
            _top_g = _items[0][1]["grade"]
            _n_tie = sum(1 for kv in _items[:len(_lines_)] if kv[1]["grade"] == _top_g)
            _tie_note = (f"; 동일 위험등급({_top_g}등급) 후보가 {_n_tie}개라 우열 없이 함께 제시합니다" if _n_tie > 1 else "")
            _head = (_safe_head + "질문하신 대로 '하나'를 확정해 추천하지는 않습니다(계좌 종류·투자 기간·손실 감내 수준을 확인하지 않아 적합하다고 단정할 수 없습니다). "
                     "다만 현재 확인된 자료 중에서는 아래 상품을 우선 검토 후보로 둘 수 있습니다(투자설명서의 위험등급 체계: 1등급 매우 높은 위험 ~ 6등급 매우 낮은 위험):\n\n"
                     "대표 검토 후보(조건부 — " + _crit + _tie_note + "):\n" + "\n".join(_lines_[:_n_tie]) +
                     (("\n\n비교 후보:\n" + "\n".join(_lines_[_n_tie:])) if len(_lines_) > _n_tie else ""))
            return (_head + "\n\n하나로 확정하려면 계좌 종류(연금저축/IRP)·투자 기간·손실 감내 수준이 더 필요합니다. 알려주시면 제공된 자료 범위에서 후보를 좁혀 드리겠습니다.")
        return (_head + "\n".join(_lines_) +
                ("\n\n" + ("하나로 좁히려면 " if _one else "후보를 좁히려면 ") +
                 "투자 기간·손실 감내 수준·계좌 종류(연금저축/IRP)가 더 필요합니다. 알려주시면 제공된 자료 범위에서 후보를 좁혀 드리겠습니다."))   # v13.62(T11): 역질문 마무리
    return ("문의하신 조건에 맞는 특정 상품을 제공된 자료 안에서 확정하지 못했습니다. 현재 확인된 자료만으로 특정 상품을 추천하기보다, "
            "투자 기간·손실 감내 수준·계좌 종류(연금저축/IRP)를 추가로 확인한 뒤 후보를 좁히는 것이 적절합니다. 알려주시면 제공된 자료 범위에서 다시 확인해 드리겠습니다.")


def recommend_contract(ans, used):
    body, tail = (ans.split("[참고 문서]", 1) + [""])[:2]
    tail = ("[참고 문서]" + tail) if "[참고 문서]" in ans else ""
    _norm = lambda t: re.sub(r"\s+", "", t)
    _docs = [(c.get("source", ""), _norm(c.get("text", ""))) for c in used]
    removed, _fixed_box = [], [0]
    lines = body.split("\n")
    out = []
    _skip_blk = False                                             # v13.52(T11 실측): 머리말 상품이 제거되면 그 블록의 항목줄(설명)도 함께 제거
    for ln0 in lines:
        _is_head = bool(ln0.strip()) and not re.match(r"^\s*[-•·*]\s", ln0)
        if not ln0.strip() or (_is_head and re.match(r"^\s*\d+[.)]\s", ln0)):
            _skip_blk = False
        if _skip_blk and re.match(r"^\s*[-•·*]\s", ln0):
            continue
        # 문장 단위로 처리: 같은 줄의 다른(실재) 상품 문장은 남긴다
        _sents = re.split(r"(?<=[.!?])\s+", ln0)
        _kept = []
        for ln in _sents:
            drop = False
            ln, drop = _rc_sentence(ln, _docs, removed, _fixed_box)
            if not drop:
                _kept.append(ln)
        if ln0.strip() and not "".join(_kept).strip():
            if _is_head:
                _skip_blk = True
            continue
        out.append(" ".join(_kept))
    fixed = _fixed_box[0]
    body = "\n".join(out)
    removed = list(dict.fromkeys(removed))
    if removed and not (_PROD_SPAN.search(body) or _PROD_CITE.search(body)):
        # 근거 미연결 상품을 지우고 나니 상품이 하나도 없다 → 설명 조각 대신 근거 자료 발췌로 대체(빈 추천 방지)
        # v13.55(T11 실측): 원문 덤프 대신 검색된 투자설명서에서 코드가 읽은 (상품명, 위험등급, 출처) 목록으로 대체 / v13.65: 함수로 분리(렌더러 공용)
        body = _rc_fallback_body(used, _question_hint[0] if _question_hint else "")
        _fixed_box[0] += 1
    # v13.32 [계약 2c — 상품별 비보장 고지]: 상품이 언급된 문단마다 '보장되지 않' 고지가 없으면 그 문단 끝에 표준 문장을 붙인다.
    #   예금·원리금보장 문단은 제외. 질문이 안정형(안정·안전·원금)인데 상품이 높은위험(1·2등급/높은위험)이면 위험을 먼저 명시한다.
    _paras = body.split("\n\n")
    _stable_q = bool(re.search(r"안정|안전|원금", _question_hint[0])) if _question_hint else False
    _added = 0
    for _pi, _p in enumerate(_paras):
        if re.search(r"예금|원리금\s*보장|원리금보장|ELB|DLB", _p) or _p.lstrip().startswith("※"):
            continue
        _pm = _PROD_SPAN.search(_p) or _PROD_CITE.search(_p)     # v13.46: 띄어쓰기 상품명 전체 우선('증권전환형자투자신탁은(는)' 조각 방지)
        if not _pm:
            continue
        _lines = _p.split("\n")
        if _stable_q and re.search(r"높은\s*위험|매우\s*높은\s*위험|\(?\s*(?:위험\s*등급\s*)?[12]\s*등급", _p) \
                and not re.search(r"안정형\s*후보로\s*보기", _p):
            _lines.insert(1, " - 위험 고지: 이 상품은 높은위험 등급으로 주가·환율·분배금 변동에 따라 원금 손실이 발생할 수 있어, "
                             "안정형 후보로 보기 어렵습니다(참고용 후보).")
            _added += 1
        if not re.search(r"보장되지\s*않|보장은\s*아님|보장되는\s*상품은\s*아닙", _p):
            _nm = _pm.group(0).strip("·-")
            _lines.append(f" - 유의: {_nm}은(는) 실적배당형으로, 투자원금과 수익(분배금)은 보장되지 않습니다.")   # 상품명 포함(중복 제거 회피)
            _added += 1
        _paras[_pi] = "\n".join(_lines)
    if _added:
        body = "\n\n".join(_paras)
        _fixed_box[0] += _added
    if removed:
        body = body.rstrip() + ("\n\n※ " + ", ".join(f"'{r}'" for r in removed[:3]) +
                                "은(는) 사용한 근거 문서에서 확인되지 않아 추천 후보에서 제외했습니다.")
    note = ""
    if removed or fixed:
        note = f" (추천 계약: 근거 미연결 상품 {len(removed)}건 제외, 등급 교정/차단 {fixed}건)"
    return (body.rstrip() + ("\n\n" + tail if tail else "")), note


def _rc_sentence(ln, _docs, removed, _fixed_box):
    """recommend_contract 의 문장 단위 검사 → (문장, 차단 여부)"""
    _norm = lambda t: re.sub(r"\s+", "", t)
    drop = False
    if True:
        for m in _PROD_CITE.finditer(ln):
            nm = m.group(0).strip("·-")
            core = _norm(re.sub(r"(?:증권자?투자신탁|투자신탁|펀드|ETF).*$", "", nm))
            if len(core) < 4 or _PROD_GENERIC.fullmatch(core):
                continue
            fact = next((f for f in PRODUCT_FACTS if re.search(f["key"], nm)), None)
            hit_docs = [t for s0, t in _docs if core in t]
            if not hit_docs and not fact:
                drop = True; removed.append(nm); break         # 근거 문서에 없는 상품 → 줄 차단
            # 등급 주장 검증: 이름 뒤 40자 안의 'N등급'
            _bad = re.search(r"(?<![\d.])\d{2,}\s*등급", ln[m.end(): m.end() + 60])
            if _bad:                                              # v13.38(R2 실측 '62등급'): 1~6 밖의 등급 표기는 차단
                ln = ln[: m.end()] + re.sub(r"(?<![\d.])\d{2,}\s*등급", "(위험등급: 자료에서 확인 필요)", ln[m.end(): m.end() + 60], count=1) + ln[m.end() + 60:]
                _fixed_box[0] += 1
            # v13.45(M2 실측 '5등급 및 6등급'): 등급 창은 다음 상품명 앞까지로 자르고, 창 안에 등급이 정확히 하나일 때만 교정한다
            #   (두 상품을 나란히 쓴 문장에서 앞 상품의 등급을 뒤 상품 값으로 덮어쓰던 오류 차단)
            _nx = next((mm.start() for mm in _PROD_CITE.finditer(ln, m.end()) if mm.start() > m.end()), len(ln))
            _win = ln[m.end(): min(m.end() + 40, _nx)]
            _gs = re.findall(r"(?<![\d.])(\d)\s*등급", _win)
            g = re.search(r"(?<![\d.])(\d)\s*등급", _win) if len(_gs) == 1 and len(re.findall(r"(?<![\d.])\d\s*등급", ln)) == 1 else None
            if g:
                if fact:
                    ok_g = re.match(r"(\d)", fact["grade"]).group(1)
                else:
                    gs = set()
                    for t in hit_docs:
                        gs.update(re.findall(r"투자위험등급(\d)등급|위험등급(\d)등급|(\d)등급\[", t))
                    gs = {x for tup in gs for x in tup if x}
                    ok_g = next(iter(gs)) if len(gs) == 1 else None
                if ok_g and g.group(1) != ok_g:
                    ln = ln[: m.end()] + re.sub(r"(\d)(\s*등급)", lambda mm: ok_g + mm.group(2), ln[m.end(): m.end() + 40], count=1) + ln[m.end() + 40:]
                    _fixed_box[0] += 1
                elif not ok_g:
                    ln = ln[: m.end()] + re.sub(r"\(?\s*위험\s*등급\s*\d\s*등급\s*\)?", "(위험등급: 자료에서 확인 필요)", ln[m.end(): m.end() + 40], count=1) + ln[m.end() + 40:]
                    _fixed_box[0] += 1
    return ln, drop


# v13.42/43 [추천 렌더러 — 결정적 구조화(LLM 호출 없음)]
#   추천 답변의 '상품 블록'(상품명이 든 문단/번호 항목 + 항목줄)을 근거 기준으로 같은 구조로 다시 그린다.
#   - 블록 내 순서: 머리말 → 위험 고지 → 본문 항목(원문 유지) → 근거 문서(위험등급·출처는 코드가 근거에서 읽음) → 유의(표준 문장, 1개)
#   - 위험등급·출처는 정답표(PRODUCT_FACTS) 또는 사용한 근거 문서(R2_ 투자설명서) 원문에서만 읽는다. 못 읽으면 쓰지 않는다.
#   - 블록 안의 'N등급'이 근거 등급과 다르면 근거 값으로 교정(척도 표현 '6등급 중'은 제외).
#   - 상품이 둘 이상 섞인 블록은 표준 유의 문장만 끝으로 모으고 나머지는 불변. 항목줄이 없는 산문 블록은 불변.
#   - v13.43: 빈 줄 없이 이어진 '1. … / 2. …' 목록도 번호 줄에서 블록을 나눈다(실측 M2 미적용 원인).
_RR_BUL = re.compile(r"^(\s*[-•·*]\s+)")
_RR_NUM = re.compile(r"^\s*\d+[.)]\s")
_RR_CANON = re.compile(r"실적배당형.{0,80}보장되지\s*않")
_RR_RISKNOTE = re.compile(r"^\s*[-•·*]\s*위험\s*고지\s*[:：]")
_RR_SRC = re.compile(r"[\w.\-]+\.(?:pdf|docx|xlsx|xls|txt|csv|hwp|pptx)")


def _rr_core(nm):
    """상품 식별 키: 공백·따옴표만 제거한 전체 표기(접미어 '자투자신탁'·'[주식]'까지 보존 — 삼성클래식 주식형/채권형처럼
    앞부분이 같은 상품을 하나로 합치지 않는다)."""
    return re.sub(r"\s+", "", nm).strip("·-'\"")


def _rr_same(a, b):
    """같은 상품의 긴 표기/짧은 표기 관계(한쪽이 다른 쪽에 포함)만 동일 상품으로 본다."""
    return a in b or b in a


def _rr_generic(c):
    return len(c) < 6 or bool(_PROD_GENERIC.fullmatch(re.sub(r"(?:증권자?투자신탁|투자신탁|펀드|ETF).*$", "", c)))


def _rr_groups(text):
    """블록 안의 상품 표기를 상품별로 묶는다 → [[(키, 원표기), ...], ...]"""
    groups = []
    for m in list(_PROD_SPAN.finditer(text)) + list(_PROD_CITE.finditer(text)):
        raw = re.sub(r"은\(는\)$", "", m.group(0).strip("·-'\""))
        c = _rr_core(raw)
        if _rr_generic(c):
            continue
        g_ = next((g for g in groups if _rr_same(g[0][0], c)), None)
        if g_ is None:
            groups.append([(c, raw)])
        else:
            g_.append((c, raw))
    return groups


def _rr_evidence(nm, used, allowed):
    """상품명 → (등급 문자열 또는 None, 출처 목록). 정답표 우선, 다음은 '참고 문서에 표기된' R2_ 투자설명서 원문."""
    fact = next((f for f in PRODUCT_FACTS if re.search(f["key"], nm)), None)
    if fact:
        return fact["grade"], [fact["src"]]
    core = _rr_core(nm)
    if _rr_generic(core):
        return None, []
    srcs, grades = [], set()
    _toks = [w for w in re.findall(r"[가-힣A-Za-z0-9]{2,}", nm)
             if not re.fullmatch(r"연금|펀드|ETF|증권|주식|채권|혼합|투자신탁|자투자신탁|증권자투자신탁|제\d+호|\d+호|클래스|C-P\d?|미래에셋|삼성", w)]
    for s in dict.fromkeys(c.get("source", "") for c in used):
        if not s or (allowed and s not in allowed):
            continue
        t = re.sub(r"\s+", "", _src_text(s))
        if core not in t and not (len(_toks) >= 2 and all(w in t for w in _toks)):   # v13.51: 띄어쓰기·표기 차이 → 핵심 토큰 전부 포함으로 재대조
            continue
        srcs.append(s)
        if s.startswith("R2_"):
            _hd = t[:3000]                                            # v13.63(T11 실측 '차이나리치투게더'→코리아리치투게더 설명서): 이름이 문서 머리(상품명 영역)에
            if core not in _hd and not (len(_toks) >= 2 and all(w in _hd for w in _toks)):   #   없으면 다른 상품의 설명서 본문 언급 → 그 문서의 등급을 붙이지 않는다
                continue
            g, lab = _read_grade(_src_text(s))
            if g is not None:
                grades.add((g, (lab or _LABEL_BY_GRADE.get(g, "")).replace(" ", "")))
    if not srcs:
        return None, []
    if len(grades) == 1:
        g, lab = next(iter(grades))
        return f"{g}등급({lab})" if lab else f"{g}등급", srcs
    return None, srcs


def _rr_capital_note(head, names_text, block_text=""):
    """v13.70(M2): 머리말이 '원금 보전·원금 보장·안정' 조건인데 아래 상품이 펀드(실적배당형)면, 원리금보장형은 별도 확인이 필요함을 먼저 밝힌다(멱등)."""
    if "아래 펀드는 원금보장 상품이 아닙니다" in (block_text or ""):
        return []
    if head and re.search(r"원금\s*(?:보전|보장)|안정", head) and re.search(r"펀드|투자신탁|ETF|TDF|상장지수", names_text or "") \
            and not re.search(r"예금|원리금\s*보장|ELB|DLB", names_text or ""):
        return [" - 원금 보장이 필요하시면 예금 등 원리금보장형 상품을 별도로 확인하셔야 하며, 아래 펀드는 원금보장 상품이 아닙니다(투자원금·수익 비보장)."]
    return []


def _rr_block(lines, used, allowed, cited, st):
    """한 블록(줄 목록) → 재구성된 줄 목록. st = {"fix": n, "blk": n, "done": bool}"""
    if len(lines) < 2 or lines[0].lstrip().startswith("※") or not any(_RR_BUL.match(l) for l in lines):
        return lines
    p = "\n".join(lines)
    if re.match(r"^\s*(?:비교 후보|대표 검토 후보|조건이 정해지면)", lines[0]):
        return lines                                              # v13.75: 코드가 만든 후보 목록 블록은 재구성하지 않는다(멱등)
    groups = _rr_groups(p)
    head = None if _RR_BUL.match(lines[0]) else lines[0]
    if not groups and head is not None:
        _hm = re.match(r"^\s*\d+[.)]\s*(.+?(?:펀드|ETF|투자신탁)[^\n(]{0,14})\s*(?:\([^)]*위험\))?\s*$", head)   # v13.51(T11 '차이나 리치 투게더 연금 펀드')
        if _hm:
            groups = [[(_rr_core(_hm.group(1)), _hm.group(1).strip())]]
    if not groups:
        return lines
    rest = lines[1:] if head is not None else lines
    risk, others, caveats = [], [], []
    for l in rest:
        if _RR_RISKNOTE.match(l):
            risk.append(l)
        elif _RR_BUL.match(l) and _RR_CANON.search(l) and len(re.split(r"(?<=[.!?])\s+", l.strip())) == 1:
            caveats.append(l)
        else:
            others.append(l)
    st["done"] = True
    # v13.50(T11 실측) [엔티티 일관성]: 머리말이 상품 A인데 유의 줄·'상품 예시' 줄이 다른 상품 B를 주어로 하면 그 줄은 다른 블록에서
    #   샌 것 → 제거. (한 블록 = 한 상품)
    if head is not None:
        _hg = _rr_groups(head)
        if len(_hg) == 1:
            _hk = _hg[0][0][0]
            def _other_entity(l_):
                _g2 = _rr_groups(l_)
                return bool(_g2) and not any(_rr_same(_hk, g[0][0]) for g in _g2)
            _n0 = len(caveats) + len(others)
            caveats = [l_ for l_ in caveats if not _other_entity(l_)]
            others = [l_ for l_ in others if not (re.match(r"^\s*[-•·*]\s*상품\s*예시\s*[:：]", l_) and _other_entity(l_))]
            st["fix"] += _n0 - len(caveats) - len(others)
            groups = [g for g in groups if _rr_same(_hk, g[0][0])] or groups
    if len(groups) != 1:
        # v13.68 [복수 상품 블록 구조화] (M2 실측: 'A(5등급) 혹은 B(6등급) 같은 채권형 펀드는 비교적 안전…' — 근거 줄 없음, B의 비보장 고지 누락, 과장 서술):
        #   상품마다 (근거 등급·출처·비보장 고지)를 따로 세우고, 상품명이 든 서술 줄은 구조화 줄로 대체한다. 등급 미확인 펀드는 후보에서 제외(v13.65 원칙).
        _generic = [l for l in others if not _rr_groups(l) and "아래 펀드는 원금보장 상품이 아닙니다" not in l]   # 상품명이 없는 일반 서술 줄만 유지(고지 줄은 재생성)
        _plines, _kept = [], 0
        _rendered = st.setdefault("rendered", [])
        for g in groups:
            nm_ = max(g, key=lambda x: len(x[0]))[1]
            core_ = min(g, key=lambda x: len(x[0]))[0]
            if any(_rr_same(core_, r_) for r_ in _rendered) and (head is None or not any(_rr_same(core_, hg[0][0]) for hg in _rr_groups(head))):
                continue                                          # v13.73(M2): 앞 블록의 상품이 비교 언급으로 끼어든 경우 → 재삽입 금지
            _rendered.append(core_)
            gr_, sr_ = _rr_evidence(nm_, used, allowed)
            if not sr_ and len(core_) >= 8 and core_ != _rr_core(nm_):
                gr_, sr_ = _rr_evidence(core_, used, allowed)
            if not sr_:
                _c2 = re.sub(r"(?:증권자?투자신탁|증권상장지수|투자신탁|펀드|ETF).*$", "", _rr_core(nm_))
                if len(_c2) >= 6 and _c2 != core_:
                    gr_, sr_ = _rr_evidence(_c2, used, allowed)
            _is_fund = bool(re.search(r"펀드|투자신탁|ETF|TDF|상장지수|리츠", nm_)) and not re.search(r"예금|원리금\s*보장|ELB|DLB", nm_)
            if _is_fund and not (gr_ and gr_[0].isdigit()):
                st["drop"] = st.get("drop", 0) + 1
                st["dropped_names"] = st.get("dropped_names", []) + [nm_]
                continue
            for s_ in sr_:
                if s_ not in cited:
                    cited.append(s_)
                allowed.add(s_)
            _plines.append(" - " + nm_ + ((": 위험등급 " + gr_) if gr_ else "") + ((" — 근거 문서: " + ", ".join(sr_)) if sr_ else ""))
            if _is_fund:
                _plines.append(f" - 유의: {nm_}{_josa(nm_)} 실적배당형으로, 투자원금과 수익(분배금)은 보장되지 않습니다.")
            _kept += 1
        if not _kept:
            return []
        new = ([head] if head is not None else []) + _rr_capital_note(head, " ".join(_plines), "") + risk + _plines + _generic   # v13.70/73(M2): 고지는 머리말 바로 아래(멱등)
        st["fix"] += 1
        st["blk"] += 1
        return new
    core = min(groups[0], key=lambda x: len(x[0]))[0]             # 포함 검사용: 가장 짧은 표기
    nm = max(groups[0], key=lambda x: len(x[0]))[1]               # 표시·근거 대조용: 가장 구체적인 표기
    st.setdefault("rendered", []).append(core)                   # v13.73: 블록 간 상품 중복 방지용
    grade, srcs = _rr_evidence(nm, used, allowed)
    if not srcs and len(core) >= 8 and core != _rr_core(nm):
        grade, srcs = _rr_evidence(core, used, allowed)           # 구체 표기가 문서 표기와 다르면(괄호·호수) 짧은 표기로 재대조
    if not srcs:                                                  # v13.64(T11 실측): '…증권 상장 지수 투자신탁(주식)' 같은 긴 표기는 문서에 앞부분만 있다 → 법적 형태 앞까지로 재대조
        _core2 = re.sub(r"(?:증권자?투자신탁|증권상장지수|투자신탁|펀드|ETF).*$", "", _rr_core(nm))
        if len(_core2) >= 6 and _core2 != core:
            grade, srcs = _rr_evidence(_core2, used, allowed)
    # v13.65 [추천 후보 원칙 — 등급 미확인 펀드 블록 제거]: 위험등급이 근거 문서(정답표·해당 상품 투자설명서 머리)에서 확인되지 않은 펀드·ETF·TDF는
    #   '공격형/안정형에 적합'처럼 읽히는 후보로 제시하지 않는다(T11 실측: 다른 상품 설명서 본문 언급만으로 후보가 됨). 예금·원리금보장형은 등급 개념이 없어 제외.
    if not (grade and grade[0].isdigit()) and re.search(r"펀드|투자신탁|ETF|TDF|상장지수|리츠", nm) and not re.search(r"예금|원리금\s*보장|ELB|DLB", p):
        st["drop"] = st.get("drop", 0) + 1
        st["dropped_names"] = st.get("dropped_names", []) + [nm]
        return []
    for s_ in srcs:                                               # 본문에 인용한 출처는 출처 줄에도 있어야 한다(answer()가 src_tail에 추가)
        if s_ not in cited:
            cited.append(s_)
        allowed.add(s_)
    ind = next((_RR_BUL.match(l).group(1) for l in rest if _RR_BUL.match(l)), " - ")
    if grade and grade[0].isdigit():                              # 등급 교정: 근거 등급과 다른 'N등급'(척도 '6등급 중'·'총 N등급' 제외)
        g0 = grade[0]
        def _gfix(m):
            if m.group(1) != g0:
                st["fix"] += 1
                return g0 + m.group(2)
            return m.group(0)
        _pat = re.compile(r"(?<![\d.총])([1-6])(\s*등급)(?!\s*중)")
        others = [_pat.sub(_gfix, l) for l in others]
        if head is not None:
            head = _pat.sub(_gfix, head)
        # v13.46(R2 실측): 앞 단계가 남긴 '(위험등급: 자료에서 확인 필요)' 자리표시는 같은 블록의 근거 등급으로 채운다(근거 문서 줄과 모순 방지)
        _ph = "(위험등급: 자료에서 확인 필요)"
        if any(_ph in l for l in others):
            others = [l.replace(_ph, g0 + "등급") for l in others]
            st["fix"] += 1
        # v13.47(R2 실측): 1~6 밖의 등급 표기('16등급' 같은 오출력)는 뒤 단계가 자리표시로 바꾸기 전에 근거 등급으로 채운다
        _bad2 = re.compile(r"(?<![\d.])\d{2,}(\s*등급)")
        if any(_bad2.search(l) for l in others):
            others = [_bad2.sub(lambda mm: g0 + mm.group(1), l) for l in others]
            st["fix"] += 1
    # v13.46(R1 실측): 내용 없는 라벨 줄('- 상품 예시:')은 다음 항목 줄과 합친다
    _mg = []
    for l in others:
        if _mg and re.fullmatch(r"\s*[-•·*]\s*[가-힣 ]{2,10}\s*[:：]\s*", _mg[-1]) and _RR_BUL.match(l):
            _mg[-1] = _mg[-1].rstrip() + " " + _RR_BUL.sub("", l, count=1).strip()
            st["fix"] += 1
        else:
            _mg.append(l)
    others = _mg
    _has_nm = lambda ls: any(core in re.sub(r"\s+", "", l) for l in ls)
    if not _has_nm(([head] if head is not None else []) + risk + others) \
            and not (head is not None and re.search(r"투자신탁|펀드|ETF", head)):   # v13.50: 머리말이 이미 상품명이면(정규식 밖 브랜드) 삽입 안 함
        others.insert(0, ind + "상품 예시: " + nm)                    # 상품명이 유의 문장에만 남았으면 이름 줄을 세운다
    new = ([head] if head is not None else []) + _rr_capital_note(head, nm, p) + risk + others   # v13.70(M2): 원금 보전 머리말 + 펀드 → 원리금보장형 별도 확인 고지
    if srcs and not any(s in p for s in srcs) and not any("근거 문서:" in l for l in new):
        new.append(ind + "근거 문서: " + ", ".join(srcs) + (f" — 위험등급 {grade}" if grade else " — 위험등급: 제공 자료에서 확인되지 않아 등급 기준의 적합성은 판단하지 못했습니다"))   # v13.63/64
    # v13.46: 유의 줄의 주어가 상품명 조각('증권전환형자투자신탁은(는)')이면 블록의 상품명으로 바꾼다
    _frag = re.compile(r"^(\s*[-•·*]\s*(?:유의\s*[:：]\s*)?)(?:증권자?투자신탁|투자신탁|자투자신탁|펀드)은\(는\)")
    for i_, l in enumerate(caveats):
        if _frag.match(l):
            caveats[i_] = _frag.sub(lambda mm: mm.group(1) + nm + "은(는)", l, count=1)
            st["fix"] += 1
    if caveats and any(_RR_CANON.search(l) for l in others):
        st["fix"] += len(caveats); caveats = []                    # 본문 줄에 이미 표준 문장이 녹아 있으면 별도 유의 줄은 중복
    if caveats:
        new.append(caveats[0])                                     # 표준 유의 문장은 블록당 하나, 맨 끝
        st["fix"] += len(caveats) - 1
    elif not any(_RR_CANON.search(l) for l in new) and not re.search(r"예금|원리금\s*보장|ELB|DLB", p):
        new.append(ind + f"유의: {nm}은(는) 실적배당형으로, 투자원금과 수익(분배금)은 보장되지 않습니다.")   # v13.50: 상품 블록마다 비보장 고지 보장
        st["fix"] += 1
    if new != lines:
        st["blk"] += 1
    return new


# v13.61 [산문 줄 판정 — 비교·추천 문장 계약 공통]: 표 행(| …)·※ 고지·[카드]·(머리말)·'- 항목명:' 형식의 행만 비산문.
#   '- 상품A는 … 보다 높습니다' 같은 글머리표 요약 문장은 산문으로 취급해 모든 문장 계약의 검사 대상에 넣는다(T6 실측: 글머리표 우열 문장 잔존).
_ROW_LABEL = re.compile(r"^-\s*[가-힣A-Za-z0-9·()\s/%]{2,14}\s*[:：]")
_PROSE_LEAD = re.compile(r"^\s*(?:[-•·*]\s*|\d+[.)]\s*)?")
# v13.81 [비교 결론 불변식]: '보다/더/덜/가장 … 위험·안전·안정·유리·높·낮' 꼴의 우열 판단 문장(핵심 값 미확정이면 어떤 변형도 금지)
_VERDICT = re.compile(r"(?:보다|더|덜|가장|제일|상대적으로|비교적)[^.!?\n]{0,14}?(?:위험|안전|안정|공격적|보수적|유리|낫|우위|높|낮|적합|나은|크|큽|작|많|적은)|(?:위험|안전|안정)(?:하다|합니다|적입니다)?\s*고\s*(?:할|볼|판단할)\s*수\s*있|"
                      r"(?:약간|조금|다소|살짝)\s*(?:더\s*)?(?:높|낮|비싸|싸|크|작|많|적|다양|복잡|단순|넓|좁|공격|보수|안정)")   # v13.83/86(T15): '약간 높은 편', '조금 더 다양한'
# v13.81(B7) [수익률 사실 레코드] — 투자설명서 '연평균수익률/연도별 수익률' 표를 (상품, 클래스, 유형, 기간, 지표) 레코드로 파싱한다. LLM 없음.
_RET_TBL = re.compile(
    r"\(\s*(\d)\s*\)\s*(?P<name>[가-힣A-Za-z0-9\s]{4,60}?(?:투자신탁|투자회사|증권자투자신탁|펀드)[^\n_(]{0,20}?(?:\[[^\]]{1,12}\])?)"
    r"(?:_(?P<cls>[A-Za-z]{1,3}(?:-[A-Za-z0-9]{1,3})?)\s*\((?P<cdesc>[^)]{0,40})\))?"
    r"[\s\d]{0,12}연도\s*(?P<hdr>(?:최근\s*\d\s*년차?\s*){2,6}(?:설정일\s*이후)?)\s*"
    r"(?P<dates>(?:\(\s*[\d.]+\s*~\s*[\d.]+\s*\)\s*){2,14})"
    r"투자신탁\s*(?P<vals>(?:[\d.]+\s*%\s*){2,6})(?:비교지수\s*(?P<bm>(?:[\d.]+\s*%\s*){2,6}))?")


def _ret_records(text):
    """표 하나당 {name, cls, cdesc, kind('연평균'|'연도별'), cols[(key, date)], fund{key:val}, bm{key:val}}"""
    out, seen = [], set()
    for m in _RET_TBL.finditer(text):
        hdr = m.group("hdr")
        keys = [f"{n}년차" if ch else f"{n}년" for n, ch in re.findall(r"최근\s*(\d)\s*년(차?)", hdr)]
        if re.search(r"설정일\s*이후", hdr):
            keys.append("설정일이후")
        kind = "연도별" if keys and keys[0].endswith("차") else "연평균"
        dates = re.findall(r"\(\s*([\d.]+\s*~\s*[\d.]+)\s*\)", m.group("dates"))
        dates = dates[-len(keys):] if len(dates) >= len(keys) else dates          # 청크 겹침으로 날짜가 중복되면 뒤쪽(값 직전) 것만
        vals = re.findall(r"([\d.]+)\s*%", m.group("vals"))
        bms = re.findall(r"([\d.]+)\s*%", m.group("bm") or "")
        if len(vals) < len(keys):
            continue
        rec = {"name": re.sub(r"\s+", " ", m.group("name")).strip(), "cls": (m.group("cls") or "").strip(), "cdesc": (m.group("cdesc") or "").strip(), "kind": kind,
               "cols": list(zip(keys, dates + [""] * (len(keys) - len(dates)))),
               "fund": dict(zip(keys, vals[:len(keys)])), "bm": dict(zip(keys, bms[:len(keys)]))}
        sig = (rec["name"], rec["cls"], kind, tuple(sorted(rec["fund"].items())))
        if sig in seen:
            continue
        seen.add(sig); out.append(rec)
    return out


def _ret_answer(question, recs):
    """질문의 기간(최근 N년/설정일이후)·클래스에 맞는 레코드로 코드 답변을 만든다. 맞는 레코드가 없으면 None."""
    _mN = re.search(r"최근\s*(\d)\s*년|(\d)\s*년\s*(?:수익률|성과|실적)", question)
    key = (f"{_mN.group(1) or _mN.group(2)}년" if _mN else ("설정일이후" if re.search(r"설정일|설정\s*이후|설정\s*후", question) else "1년"))
    _mc = re.search(r"\b([A-Za-z]{1,3}(?:-[A-Za-z0-9]{1,3})?)\s*(?:클래스|형|종류)?\b", question)
    qcls = _mc.group(1) if _mc and _mc.group(1).upper() not in ("IRP", "DC", "DB", "ETF", "TDF", "ISA", "MMF", "ELB", "DLB", "RP") else ""
    avg = [r for r in recs if r["kind"] == "연평균" and key in r["fund"]]
    if not avg:
        return None
    base = [r for r in avg if not r["cls"]] or avg[:1]
    if qcls:
        pick = [r for r in avg if r["cls"].upper() == qcls.upper()]
        if not pick:
            return None
        base = pick
    b = base[0]
    dt = dict(b["cols"]).get(key, "")
    lab = "설정일 이후" if key == "설정일이후" else f"최근 {key}"
    lines = [f"{b['name']}의 {lab} 연평균 수익률" + (f"(기준 기간 {dt})" if dt else "") + "은 투자설명서 기준으로 다음과 같습니다."]
    lines.append(f"- 투자신탁{'(' + b['cls'] + ' 클래스: ' + b['cdesc'] + ')' if b['cls'] else '(운용펀드 전체 기준)'}: {b['fund'][key]}%" + (f" / 비교지수: {b['bm'][key]}%" if b["bm"].get(key) else ""))
    if not qcls:                                                   # v13.82: 클래스 미지정이면 전체 값만 답하고, 클래스별 값은 요청 시 안내(혼동 방지)
        others = sorted({r["cls"] for r in avg if r["cls"] and key in r["fund"]})
        if others:
            lines.append(f"※ 판매 클래스({'·'.join(others)})별 수익률은 위 전체 값과 다르며, 클래스를 지정해 주시면 해당 클래스의 값을 안내해 드립니다.")
    yr = [r for r in recs if r["kind"] == "연도별" and (key + "차") in r["fund"] and (not r["cls"])]
    if yr and key not in ("설정일이후", "1년") and yr[0]["fund"][key + "차"] != b["fund"][key]:
        ydt = dict(yr[0]["cols"]).get(key + "차", "")
        lines.append(f"※ 같은 문서의 '연도별 수익률' 표에 있는 '최근 {key}차' {yr[0]['fund'][key + '차']}%는 {lab} 연평균이 아니라 " + (f"{ydt} " if ydt else "") + "한 해의 수익률입니다.")
    lines.append("※ 과거의 수익률이나 성과는 미래의 수익을 보장하지 않습니다.")       # v13.82: 레코드 답변이 본문을 대체하므로 고지를 안에 포함
    return "\n".join(lines)



def _is_prose_line(ln):
    st = ln.strip()
    if not st or st.startswith(("|", "※", "[", "(")) or "|" in st:
        return False
    return not _ROW_LABEL.match(st)


