    (re.compile(r"낮을\s*수\s*있으나\s*없지는\s*않으며\."), "낮을 수 있지만, 손실 가능성이 없는 것은 아닙니다."),   # v13.72: 이전 교체의 끊긴 어미 복구
    (re.compile(r"(?:상대적으로\s*)?안전한\s*투자를\s*(?:선호|원|추구)하는"), "위험등급이 상대적으로 낮은 상품을 선호하는"),   # v13.76
    (re.compile(r"(?:장기적으로\s*)?(?:높은\s*)?성장\s*가능성(?:을|이)\s*(?:제공|약속)(?:합니다|하며|하고|할\s*수\s*있습니다)"), "성장 가능성이 있으나 손실 가능성도 있습니다"),   # v13.74(M2)
    (re.compile(r"(?:장기적으로\s*)?높은\s*수익을\s*기대할\s*수\s*있는"), "수익 가능성이 있으나 손실 위험도 있는"),   # v13.75(M2)
    (re.compile(r"성장\s*잠재력이\s*(?:크|높)(?:지만|으나|고|습니다)"), "성장 가능성이 있을 수 있으나"),
